INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7D15C720F54C7A5C3F5A','public_higher_education_research',NULL,'News Archive Item','https://www.ufs.ac.za/templates/news-archive/campus-news/2026/september/ufs-student-leaders-gain-african-perspectives-through-global-citizenship-programme-in-kenya',NULL,'University of the Free State','UFS EDCM','South Africa','Africa','public_university',NULL,NULL,'2026-10-05T19:27:05.083Z','institutional_primary','en','Being a global citizen in Africa today means learning to see beyond the boundaries of one''s own experience.Through the Global Citizenship Developmental Programme, student leaders are doing just that in Kenya, engaging with universities and public institutions to deepen their understanding of leadership, governance and development on the continent. The programme forms part of the UFS Division of Student Affairs'' commitment to developing globally competent graduates who are socially responsible and equipped to contribute meaningfully to society.Now in its third year, the programme has expanded from partnerships in Southern Africa to East Africa through a collaboration with the Co-operative University of Kenya (CUK). African universities learning from one anotherAt CUK, the UFS delegation engaged with university leadership on the role of higher education in responding to social and economic','Being a global citizen in Africa today means learning to see beyond the boundaries of one''s own experience.Through the Global Citizenship Developmental Programme, student leaders are doing just that in Kenya, engaging with universities and public institutions to deepen their understanding of leadership, governance and development on the continent. The programme forms part of the UFS Division of Student Affairs'' commitment to developing globally competent graduates who are socially responsible and equipped to contribute meaningfully to society.Now in its third year, the programme has expanded from partnerships in Southern Africa to East Africa through a collaboration with the Co-operative University of Kenya (CUK). African universities learning from one anotherAt CUK, the UFS delegation engaged with university leadership on the role of higher education in responding to social and economic',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ufs.ac.za/templates/news-archive/campus-news/2026/september/ufs-student-leaders-gain-african-perspectives-through-global-citizenship-programme-in-kenya',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','38a3bfe076a6f2e20d1674fa6e9fd810d51f8329d100b59c28178684734a9761','7d15c720f54c7a5c3f5a4fa84ca7e29f245015a3aa5167616e8d50f04246acf0',1,1,1,1 FROM sources WHERE root_url='https://www.ufs.ac.za/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
