INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F0A03711901685CABE21','research',NULL,'Academy of Mathematics and Systems Science','http://english.amss.cas.cn/',NULL,'Academy of Mathematics and Systems Science',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-05T19:25:35.132Z','institutional_primary','en','The Academy of Mathematics and Systems Science (AMSS) of the Chinese Academy of Sciences (CAS), was founded in December 1998 with the integration of the Institute of Mathematics (established 1952), the Institute of Applied Mathematics (established 1979), the Institute of Systems Science (established 1979), the Institute of Computational Mathematics and Scientific/Engineering Computing (established 1995). CAS Academician Prof. YANG Lo was its founding president, CAS Academician Prof. GUO Lei was the second president, CAS Academician Prof. XI Nanhua and Prof. WANG Yuefei were the third co-presidents, and CAS Academician Prof. XI Nanhua is the current president.','The Academy of Mathematics and Systems Science (AMSS) of the Chinese Academy of Sciences (CAS), was founded in December 1998 with the integration of the Institute of Mathematics (established 1952), the Institute of Applied Mathematics (established 1979), the Institute of Systems Science (established 1979), the Institute of Computational Mathematics and Scientific/Engineering Computing (established 1995). CAS Academician Prof. YANG Lo was its founding president, CAS Academician Prof. GUO Lei was the second president, CAS Academician Prof. XI Nanhua and Prof. WANG Yuefei were the third co-presidents, and CAS Academician Prof. XI Nanhua is the current president.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.amss.cas.cn/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3e9fff6d4a350d839d3829b291f824d29b3723689b287b5665c363b0537dbb36','f0a03711901685cabe21fb7d7e1ef1ad056453815b7b15b08193036ab97956a7',1,1,1,1 FROM sources WHERE root_url='http://english.amss.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
