INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A485152271AB34248FB0','research',NULL,'Institute of Vertebrate Paleontology and Paleoanthropology, Chinese Academy of Sciences','http://english.ivpp.cas.cn/',NULL,'Institute of Vertebrate Paleontology and Paleoanthropology','The Institute of Vertebrate Paleontology and Paleoanthropology (IVPP), Chinese Academy of Sciences (CAS)','China','Asia','official_research_institution',NULL,NULL,'2026-10-05T19:31:21.333Z','institutional_primary','en','The Institute of Vertebrate Paleontology and Paleoanthropology (IVPP), Chinese Academy of Sciences (CAS), is one of world’s premiere paleontological institutions. IVPP researchers study the institute’s namesake disciplines, vertebrate paleontology and paleoanthropology, and their related areas of geological and biological sciences as well as Paleolithic archaeology.Vertebrate paleontological research focuses on the morphology, taxonomy, phylogeny, paleoecology, and spatial and temporal distribution of the various vertebrate groups, as well as other relevant biogeographical, paleoclimatological, developmental and molecular biological problems. The paleoanthrological study mainly deals with origin and evolutionary history of fossil human and Paleolithic archeology. Moreover, the study of applied anthropology and physical anthropology has also been emphasized in recent years.','The Institute of Vertebrate Paleontology and Paleoanthropology (IVPP), Chinese Academy of Sciences (CAS), is one of world’s premiere paleontological institutions. IVPP researchers study the institute’s namesake disciplines, vertebrate paleontology and paleoanthropology, and their related areas of geological and biological sciences as well as Paleolithic archaeology.Vertebrate paleontological research focuses on the morphology, taxonomy, phylogeny, paleoecology, and spatial and temporal distribution of the various vertebrate groups, as well as other relevant biogeographical, paleoclimatological, developmental and molecular biological problems. The paleoanthrological study mainly deals with origin and evolutionary history of fossil human and Paleolithic archeology. Moreover, the study of applied anthropology and physical anthropology has also been emphasized in recent years.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.ivpp.cas.cn/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c751c944791ac1ea74a9f139002f278ed9f9d85636d4bc8c0e5a77defdbd6a77','a485152271ab34248fb00a715507fc1a7ae5a97dba69d94dfb774879191fb8d6',1,1,1,1 FROM sources WHERE root_url='http://english.ivpp.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
