INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B40D9BE5C9EF88709A8E','research',NULL,'Twelfth Annual “Research Fronts Report” Highlights Hot and Emerging Fields----Institutes of Science and Development, Chinese Academy of Sciences','http://english.casisd.cn/media/202512/t20251204_1134669.html',NULL,'Institutes of Science and Development',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-05T19:31:22.220Z','institutional_primary','en','To highlight fast-moving and emerging specialty areas of science, Clarivate has once again partnered with the Chinese Academy of Sciences (CAS) in a yearly report on the hottest fields in research, including data on the countries and institutions producing the work. The latest annual edition, Research Fronts 2025, marks the twelfth collaboration between Clarivate and the CAS. The new report was released on December 3.','To highlight fast-moving and emerging specialty areas of science, Clarivate has once again partnered with the Chinese Academy of Sciences (CAS) in a yearly report on the hottest fields in research, including data on the countries and institutions producing the work. The latest annual edition, Research Fronts 2025, marks the twelfth collaboration between Clarivate and the CAS. The new report was released on December 3.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.casisd.cn/media