INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-5DC7F59F1D34485D64B2','research',NULL,'Nanjing Institute of Geography and Limnology, Chinese Academy of Sciences','http://english.niglas.cas.cn/',NULL,'Nanjing Institute of Geography and Limnology',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-05T19:31:30.389Z','institutional_primary','en','Freshwater ecosystems worldwide have been suffering from declining oxygen levels—a trend known as deoxygenation—that threatens biodiversity, fisheries, and ecosystem stability. However, a new study published on June 26 in Nature Geoscience offers hope: targeted nutrient management via wastewater control can reverse this trajectory, even in the face of rapid climate warming.Led by Professor ZHOU Yongqiang from the Nanjing Institute of Geography and Limnology of the Chinese Academy of Sciences, an international research team analyzed 18 years of monthly data (2005–2022) from 972 rivers and 354 lake sites across China. Their findings challenge the prevailing narrative that aquatic deoxygenation is an unstoppable consequence of human development and global warming.Although surface waters warmed by 1.2 °C per decade, a rate higher than the global average, the researchers found that dissolved ','Freshwater ecosystems worldwide have been suffering from declining oxygen levels—a trend known as deoxygenation—that threatens biodiversity, fisheries, and ecosystem stability. However, a new study published on June 26 in Nature Geoscience offers hope: targeted nutrient management via wastewater control can reverse this trajectory, even in the face of rapid climate warming.Led by Professor ZHOU Yongqiang from the Nanjing Institute of Geography and Limnology of the Chinese Academy of Sciences, an international research team analyzed 18 years of monthly data (2005–2022) from 972 rivers and 354 lake sites across China. Their findings challenge the prevailing narrative that aquatic deoxygenation is an unstoppable consequence of human development and global warming.Although surface waters warmed by 1.2 °C per decade, a rate higher than the global average, the researchers found that dissolved ',NULL,NULL,NULL,NULL,NULL,'10.1021/acs.est.2c07181','10.1021/acs.est.2c07181',NULL,'free','primary','not_applicable',NULL,NULL,'http://english.niglas.cas.cn/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','d163c6c0726773a175c0623e2797afa9038b2e0cdc0486fecf36c0683f28e4cb','5dc7f59f1d34485d64b23ab4f7b57e70c6a7cb507c852c702bfaba51105b2ab6',1,1,1,1 FROM sources WHERE root_url='http://english.niglas.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
