INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-FEE7CA837F4CA1BF7F83','research',NULL,'Purple Mountain Observatory','https://english.pmo.cas.cn/',NULL,'Purple Mountain Observatory','author,中国科学院计算机网络信息中心','China','Asia','official_research_institution',NULL,NULL,'2026-10-05T19:32:01.449Z','institutional_primary','en','The Purple Mountain Observatory (PMO) evolved from the former Institute of Astronomy, which was established in 1928 as one of the first eight institutes of the Academia Sinica. In 1934, the institute completed the construction of the observatory at Purple Mountain in Nanjing and the Institute of Astronomy changed its name to PMO in 1950. PMO is known as the “Cradle of Modern Astronomy in China” not only because it was China’s first modern astronomical institute, but also because it was the originator of most subdisciplines of Chinese astronomy and the sponsor of subsequent CAS astronomical institutions.','The Purple Mountain Observatory (PMO) evolved from the former Institute of Astronomy, which was established in 1928 as one of the first eight institutes of the Academia Sinica. In 1934, the institute completed the construction of the observatory at Purple Mountain in Nanjing and the Institute of Astronomy changed its name to PMO in 1950. PMO is known as the “Cradle of Modern Astronomy in China” not only because it was China’s first modern astronomical institute, but also because it was the originator of most subdisciplines of Chinese astronomy and the sponsor of subsequent CAS astronomical institutions.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.pmo.cas.cn/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','1cf74270777ab3f4f7ffbe3488fbb16b7db12fbf800884bd583c3b3002a9d2c9','fee7ca837f4ca1bf7f83c513164e39d6198141bb4ca02dcb6bd4767b08e608fa',1,1,1,1 FROM sources WHERE root_url='http://english.pmo.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'purple mountain observatory the purple mountain observatory pmo evolved from the former institute of astronomy which was established in 1928 as one of the first eight institutes of the academia sinica. in 1934 the institute completed the construction of the observatory at purple mountain in nanjing and the institute of astronomy changed its name to pmo in 1950. pmo is known as the cradle of modern astronomy in china not only because it was china s first modern astronomical institute but also because it was the originator of most subdisciplines of chinese astronomy and the sponsor of subsequent cas astronomical institutions. research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='fee7ca837f4ca1bf7f83c513164e39d6198141bb4ca02dcb6bd4767b08e608fa' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
