INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-3DBDCB53E6F386E59B0D','research',NULL,'Headline----Shanghai Institute of Material Medical Chinese Academy of Sciences','http://english.simm.cas.cn/News/Headline/202607/t20260724_1179008.html',NULL,'Shanghai Institute of Materia Medica',NULL,'China','Asia','official_research_institution','2026-07-24',NULL,'2026-10-05T19:32:19.728Z','institutional_primary','en','Allergic airway inflammation is a key pathological basis for the onset and progression of asthma. When environmental allergens such as pollen, house dust mites, and fungal proteases enter the airway, they first act on lung epithelial cells and induce the release of alarmins, including IL-33. IL-33 then activates type 2 innate lymphoid cells (ILC2s), leading to eosinophil infiltration, mucus production, and airway tissue damage.','Allergic airway inflammation is a key pathological basis for the onset and progression of asthma. When environmental allergens such as pollen, house dust mites, and fungal proteases enter the airway, they first act on lung epithelial cells and induce the release of alarmins, including IL-33. IL-33 then activates type 2 innate lymphoid cells (ILC2s), leading to eosinophil infiltration, mucus production, and airway tissue damage.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.simm.cas.cn/News/Headline/202607/t20260724_1179008.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','f08c53855993ecdf46809c184d374f38cbce6440848c4bef9ff0e6ab2e0f3ec5','3dbdcb53e6f386e59b0d9fecba7d8c5fbb2132e7a9f88c3ca15d348d0944a009',1,1,1,1 FROM sources WHERE root_url='http://english.simm.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
