INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E89C4D91315421A4C455','research',NULL,'Shanghai Institute of Technical Physics discovers the “Exciton-Polariton Photodetection Effect”State Key Laboratory of Infrared Physics----SHANGHAI INSITUTE OF TECHNICAL PHYSICS OF THE CHINESE ACADEMY OF SCIENCES','http://english.sitp.cas.cn/Research/rp/202601/t20260123_1146456.html',NULL,'Shanghai Institute of Technical Physics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-05T19:32:54.201Z','institutional_primary','en','On January 17, Professors Weida Hu and Jinshui Miao of the State Key Laboratory of Infrared Physics, Shanghai Institute of Technical Physics (SITP), Chinese Academy of Sciences (CAS), have proposed a “exciton-polariton photodetection effect” for the first time. By introducing self-hybridized exciton-polaritons as the dominant transport quasiparticles under non-equilibrium conditions, this work reshapes the generation and transport mechanisms of photocarriers in photodiodes. The study breaks through the physical bottleneck of thermal-equilibrium exciton diffusion in conventional devices and provides a new approach for developing high-efficiency, high-speed photodetection. The result was published in Nature Communications titled “Exciton-polariton photodiodes.”','On January 17, Professors Weida Hu and Jinshui Miao of the State Key Laboratory of Infrared Physics, Shanghai Institute of Technical Physics (SITP), Chinese Academy of Sciences (CAS), have proposed a “exciton-polariton photodetection effect” for the first time. By introducing self-hybridized exciton-polaritons as the dominant transport quasiparticles under non-equilibrium conditions, this work reshapes the generation and transport mechanisms of photocarriers in photodiodes. The study breaks through the physical bottleneck of thermal-equilibrium exciton diffusion in conventional devices and provides a new approach for developing high-efficiency, high-speed photodetection. The result was published in Nature Communications titled “Exciton-polariton photodiodes.”',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'http://english.sitp.cas.cn/Research/rp/202601/t20260123_1146456.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','67beaa709eb06ccc6b752ae887e5cc387a23e5b1923c924bc5b9251808fcf5dc','e89c4d91315421a4c4553fbda1410772c1f020e1aafdc9bc7bd736b08da13f29',1,1,1,1 FROM sources WHERE root_url='http://english.sitp.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
