INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-AAD2511A036A21053737','research',NULL,'सीएसआईआर-भारतीय समवेत औषध संस्थान &#8211; Council of Scientific & Industrial Research','https://iiim.res.in/',NULL,'CSIR-In',NULL,'India','Asia','government_research_institute',NULL,NULL,'2026-10-05T19:28:31.270Z','institutional_primary','en','The mandate of IIIM is to be an internationally competitive centre of excellence in all facets of natural products research and technology, including (a) discovery of novel pharmacologically active natural products from plants and microbial species and translating them into drug leads and candidates by medicinal chemistry, preclinical pharmacology and clinical development. This approach is pursued both in NCE as well as botanical herbal mode; (b) Preclinical and clinical validation and establishment of mechanism of action of drugs used in various Indian systems of Medicines (Ayurveda, Unani, Siddha and other Indigenous systems of medicine); (c) develop agro-technologies and commercial cultivation of high value medicinal and aromatic plants from Western Himalayas including Kashmir Valley and Laddkh for national and international markets; and (d) to work with Indian and global pharmaceutic','The mandate of IIIM is to be an internationally competitive centre of excellence in all facets of natural products research and technology, including (a) discovery of novel pharmacologically active natural products from plants and microbial species and translating them into drug leads and candidates by medicinal chemistry, preclinical pharmacology and clinical development. This approach is pursued both in NCE as well as botanical herbal mode; (b) Preclinical and clinical validation and establishment of mechanism of action of drugs used in various Indian systems of Medicines (Ayurveda, Unani, Siddha and other Indigenous systems of medicine); (c) develop agro-technologies and commercial cultivation of high value medicinal and aromatic plants from Western Himalayas including Kashmir Valley and Laddkh for national and international markets; and (d) to work with Indian and global pharmaceutic',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://iiim.res.in/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','21327baebbb47413eddb4d211edf8b9101c43f26fcf488e90895501f9b0c232a','aad2511a036a21053737357607ae70dd292e4c8ec570bf0371c1996eae81874c',1,1,1,1 FROM sources WHERE root_url='https://iiim.res.in/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'स एसआईआर-भ रत य समव त औषध स स थ न 8211 council of scientific industrial research the mandate of iiim is to be an internationally competitive centre of excellence in all facets of natural products research and technology including a discovery of novel pharmacologically active natural products from plants and microbial species and translating them into drug leads and candidates by medicinal chemistry preclinical pharmacology and clinical development. this approach is pursued both in nce as well as botanical herbal mode b preclinical and clinical validation and establishment of mechanism of action of drugs used in various indian systems of medicines ayurveda unani siddha and other indigenous systems of medicine c develop agro-technologies and commercial cultivation of high value medicinal and aromatic plants from western himalayas including kashmir valley and laddkh for national and international markets and d to work with indian and global pharmaceutic research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='aad2511a036a21053737357607ae70dd292e4c8ec570bf0371c1996eae81874c' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
