INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9D97CCCB4B34ABB790B9','public_higher_education_research',NULL,'研究実績 - 北見工業大学','https://www.kitami-it.ac.jp/brand/archives/',NULL,'北見工業大学',NULL,'Japan','Asia','japanese_national_university',NULL,NULL,'2026-10-05T19:35:28.462Z','institutional_primary','ja','北極海や南極海、オホーツク海などの氷海で見られる海氷は、地球の気候変動に敏感に反応してその量が変化し、同時に海氷の増減が大気や海洋に大きな影響を及ぼしています。オホーツク海に面するサロマ湖や北極、南極の極域をフィールドに、氷状観測手法の開発を行っています。','北極海や南極海、オホーツク海などの氷海で見られる海氷は、地球の気候変動に敏感に反応してその量が変化し、同時に海氷の増減が大気や海洋に大きな影響を及ぼしています。オホーツク海に面するサロマ湖や北極、南極の極域をフィールドに、氷状観測手法の開発を行っています。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.kitami-it.ac.jp/brand/archives/',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','756f89cff01c7eb7a385caadf4dd8a69278a6e45ba3fa81feca4d869871a488d','9d97cccb4b34abb790b91ad513edfa4c692f4daa3cbc825adbda003a130c42b8',1,1,1,1 FROM sources WHERE root_url='https://www.kitami-it.ac.jp/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
