INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-85C5B86717524377B60C','public_higher_education_research',NULL,'千葉大学が文部科学省・国立研究開発法人科学技術振興機構（JST）の「産業・科学革新人材事業（INSIGHT）」に採択されました | 国立大学法人 千葉大学｜Chiba University','https://www.chiba-u.ac.jp/news/notice/jstinsight_1.html',NULL,'千葉大学',NULL,'Japan','Asia','japanese_national_university',NULL,NULL,'2026-10-05T19:35:27.540Z','institutional_primary','ja','本事業は、先端技術分野を対象として産学協働による研究開発・人材育成（研究者・技術者等）の一体的な推進を通じて科学技術人材への人的資本投資を大幅に拡充するとともに、これを先行投資として、産業界から大学への複数年度にわたる投資（研究開発・人材育成）の拡大を目指す大学を支援するものです。 本学では、ライフサイエンスにおける科学とビジネスを繋ぐ「クロスボーダーイノベーター」の育成を目指し、本学の西千葉well-beingリサーチパーク(千葉県千葉市)とかずさアカデミアパーク(千葉県木更津市)、鶴岡サイエンスパーク(山形県鶴岡市)を結ぶ連携拠点「TRI-PARKS」を構築いたします。国や千葉県の戦略も踏まえ、ライフサイエンスを核とした異分野融合や多様な企業との連携を図り、教育研究の高度化及び高度人材育成の充実を担う「共創研究所」の設置等を通じて、産官学連携を強化してまいります。これらにより、研究開発と人材育成を一体的に推進し、持続的な「クロスボーダーイノベーター」の輩出を行うことで、我が国の産業競争力強化に貢献いたします。','本事業は、先端技術分野を対象として産学協働による研究開発・人材育成（研究者・技術者等）の一体的な推進を通じて科学技術人材への人的資本投資を大幅に拡充するとともに、これを先行投資として、産業界から大学への複数年度にわたる投資（研究開発・人材育成）の拡大を目指す大学を支援するものです。 本学では、ライフサイエンスにおける科学とビジネスを繋ぐ「クロスボーダーイノベーター」の育成を目指し、本学の西千葉well-beingリサーチパーク(千葉県千葉市)とかずさアカデミアパーク(千葉県木更津市)、鶴岡サイエンスパーク(山形県鶴岡市)を結ぶ連携拠点「TRI-PARKS」を構築いたします。国や千葉県の戦略も踏まえ、ライフサイエンスを核とした異分野融合や多様な企業との連携を図り、教育研究の高度化及び高度人材育成の充実を担う「共創研究所」の設置等を通じて、産官学連携を強化してまいります。これらにより、研究開発と人材育成を一体的に推進し、持続的な「クロスボーダーイノベーター」の輩出を行うことで、我が国の産業競争力強化に貢献いたします。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.chiba-u.ac.jp/news/notice/jstinsight_1.html',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','2fa179a6493af914779ae7e2b3bc1c262893ce5c2f2dbf7abe99fc6a434c6878','85c5b86717524377b60c7bde633b74e47d4e92628352d61c771ebe46347db43a',1,1,1,1 FROM sources WHERE root_url='https://www.chiba-u.ac.jp/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
