INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-591C0EE88C272ECF22BC','public_higher_education_research',NULL,'高大連携 | 公立大学法人 宮城大学 - MYU','https://www.myu.ac.jp/high-univ/',NULL,'宮城大学',NULL,'Japan','Asia','japanese_public_university',NULL,NULL,'2026-10-05T19:36:37.520Z','institutional_primary','ja','「探究的な学習」とは、2009 年 3月に示された高等学校学習指導要領の中で、右図のように問題解決的な活動が発展的に繰り返されていく一連の学習活動のことです。一言で表せば「物事の本質を探って見極めようとする一連の知的営み」であるといえます。2018年に示された新しい学習指導要領では、これまで「総合的な学習の時間」とされてきた教科が「総合的な〈探究〉の時間」に名称が変更され、その目的は「自己の在り方生き方を考えながら、よりよく課題を発見し解決していくこと」とされました。','「探究的な学習」とは、2009 年 3月に示された高等学校学習指導要領の中で、右図のように問題解決的な活動が発展的に繰り返されていく一連の学習活動のことです。一言で表せば「物事の本質を探って見極めようとする一連の知的営み」であるといえます。2018年に示された新しい学習指導要領では、これまで「総合的な学習の時間」とされてきた教科が「総合的な〈探究〉の時間」に名称が変更され、その目的は「自己の在り方生き方を考えながら、よりよく課題を発見し解決していくこと」とされました。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.myu.ac.jp/high-univ/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e82e51bdff5bf770e69c93aa24c7b3103ab551d7dd9c6ddaf4210f3855a6973d','591c0ee88c272ecf22bc00fa49829300e290377aa82b7b63664558a9db36ed9d',1,1,1,1 FROM sources WHERE root_url='https://www.myu.ac.jp/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.