INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'高大連携 公立大学法人 宮城大学 - myu 探究的な学習 とは 2009 年 3月に示された高等学校学習指導要領の中て 右図のように問題解決的な活動か 発展的に繰り返されていく一連の学習活動のことて す 一言て 表せは 物事の本質を探って見極めようとする一連の知的営み て あるといえます 2018年に示された新しい学習指導要領て は これまて 総合的な学習の時間 とされてきた教科か 総合的な 探究 の時間 に名称か 変更され その目的は 自己の在り方生き方を考えなか ら よりよく課題を発見し解決していくこと とされました public higher education research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='591c0ee88c272ecf22bc00fa49829300e290377aa82b7b63664558a9db36ed9d' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
