INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A2AA351276A89374E87F','public_higher_education_research',NULL,'【世界初】手軽なストレッチ器具「フォームローリング」に心臓の負担軽減効果｜研究活動｜宮崎公立大学（MMU）','https://www.miyazaki-mu.ac.jp/topics/researchactivities/2026/09/post-162.html',NULL,'宮崎公立大学',NULL,'Japan','Asia','japanese_public_university',NULL,NULL,'2026-10-05T19:36:48.904Z','institutional_primary','ja','過去30年以上にわたり世界の死因第１位である心血管疾患の重要な発症予測因子として左室後負荷(※)があります。ストレッチポールを使ったストレッチをすることにより、この左室後負荷が下がることを発見しました。また、これは年齢や性別を問わず効果があり、筋肉量が多い人ほど左室後負荷の低減効果が大きいことが明らかになりました。この発見は、心血管疾患の一次予防を実現する新たなヘルスケア習慣として貢献することが期待されます。','過去30年以上にわたり世界の死因第１位である心血管疾患の重要な発症予測因子として左室後負荷(※)があります。ストレッチポールを使ったストレッチをすることにより、この左室後負荷が下がることを発見しました。また、これは年齢や性別を問わず効果があり、筋肉量が多い人ほど左室後負荷の低減効果が大きいことが明らかになりました。この発見は、心血管疾患の一次予防を実現する新たなヘルスケア習慣として貢献することが期待されます。',NULL,NULL,NULL,NULL,NULL,'10.1097/HJH.0000000000004424','10.1097/HJH.0000000000004424',NULL,'free','primary','not_applicable',NULL,NULL,'https://www.miyazaki-mu.ac.jp/topics/researchactivities/2026/09/post-162.html',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','2acc07c2904713aeee1f92fb2a83b0132c530e1bf9f5d4300c8f83327489bcd7','a2aa351276a89374e87f09cbf15eeaed99864718608c71bf9b329e20b33d740a',1,1,1,1 FROM sources WHERE root_url='https://www.miyazaki-mu.ac.jp/' ON CONFLICT(canonical_hash) DO UPDATE SET consult