INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-77A79BF1F71760795847','public_higher_education_research',NULL,'論文掲載 Clinical and Health Sciences Journal | 学科からのお知らせ | 看護学科 | 山形県立保健医療大学｜山形県立保健医療大学','https://www.yachts.ac.jp/faculty/ns/news/entry-1405.html',NULL,'山形県立保健医療大学',NULL,'Japan','Asia','japanese_public_university',NULL,NULL,'2026-10-05T19:37:14.431Z','institutional_primary','ja','看護学科髙谷新講師、安保寛明教授らの論文が『Clinical and Health Sciences Journal』に掲載されました。 本研究は、看護職を対象に、看護師長のリーダーシップ（PM理論に基づくP機能：課題指向、M機能：人間関係指向）および職場ストレス要因が、看護師のワーク・エンゲージメント（WE）やストレス反応に与える影響を多群構造方程式モデリングを用いて分析を行ったものです。 16病院の看護職331名のデータを経験年数別（1〜3年、4〜9年、10年以上）に分析した結果、全群において職場ストレス要因が高いほどWEが低くストレス反応が高いこと、また人間関係指向のリーダーシップおよびWEが高いほどストレス反応が低いことが示されました。特に中堅期（4〜9年）の看護師は、他群と同等のス...','看護学科髙谷新講師、安保寛明教授らの論文が『Clinical and Health Sciences Journal』に掲載されました。 本研究は、看護職を対象に、看護師長のリーダーシップ（PM理論に基づくP機能：課題指向、M機能：人間関係指向）および職場ストレス要因が、看護師のワーク・エンゲージメント（WE）やストレス反応に与える影響を多群構造方程式モデリングを用いて分析を行ったものです。 16病院の看護職331名のデータを経験年数別（1〜3年、4〜9年、10年以上）に分析した結果、全群において職場ストレス要因が高いほどWEが低くストレス反応が高いこと、また人間関係指向のリーダーシップおよびWEが高いほどストレス反応が低いことが示されました。特に中堅期（4〜9年）の看護師は、他群と同等のス...',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.yachts.ac.jp/faculty/ns/news/entry-1405.html',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3d40faf02e049a95