INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7D4DF752C1974AEC479A','public_higher_education_research',NULL,'タイ科学技術博覧会2026（Thailand National Science and Technology Fair 2026）に出展、本学の貢献が表彰 | お知らせ | ニュース | 国立大学法人 東京農工大学','https://www.tuat.ac.jp/NEWS/info/20260828_01.html',NULL,'東京農工大学',NULL,'Japan','Asia','japanese_national_university',NULL,NULL,'2026-10-05T19:39:06.806Z','institutional_primary','ja','タイ科学技術博覧会（Thailand National Science and Technology Fair）は、年に1回開催されるタイ国最大の科学技術展覧会です。今年は8月15日から23日までの9日間、バンコクのIMPACT Exhibition Centerで開催されました。毎年、会期中には主に現地の小中学生、高校生を中心に約20万人が来場するイベントです。 開会式では、Yodchanan Wongsawat副首相兼高等教育・科学・研究・イノベーション大臣が出席されました。本学では2024年から継続的に本博覧会へ出展しており、今年で通算3回目の参加となります。 会場内の日本ブース（ジャパンパビリオン）は在タイ日本国大使館が統括し、本学のほか、日本大使館、情報通信研究機構（NICT）、科学技術振興機構（JST）、日本学術振興会（JSPS）、国際協力機構（JICA）、国際農林水産業研究センター（JIRCAS）、宇宙航空研究開発機構（JAXA）、京都大学、東京科学大学、チュラロンコン大学、折り紙ヒコーキ協会など、学術・研究機関が出展しました。 今回、本学のブースでは大学紹介、全学プロジェクトであるCOI-NEXT、J-PEAKS、SATREPSの活動内容について展示を行いました。SATREPSの展示では、プロジェクトの対象資源であるタイ産のパラゴムノキの種子（ゴム種子）の粉砕体験をしてもらい、多くの小中学生、高校生が種子の殻割に興じ好評でした。 また、これまでの本学の科学技術教育への貢献が高く評価され、高等教育・科学・研究・イノベーション省のSupachai Pathumnakul事務次官より、本学工学研究院の兼橋准教授（SATREPS代表）にトロフィーが授与されました。 引き続き、本学の国際活動を推進してまいります。','タイ科学技術博覧会（Thailand National Science and Technology Fair）は、年に1回開催されるタイ国最大の科学技術展覧会です。今年は8月15日から23日までの9日間、バンコクのIMPACT Exhibition Centerで開催されました。毎年、会期中には主に現地の小中学生、高校生を中心に約20万人が来場するイベントです。 開会式では、Yodchanan Wongsawat副首相兼高等教育・科学・研究・イノベーション大臣が出席されました。本学では2024年から継続的に本博覧会へ出展しており、今年で通算3回目の参加となります。 会場内の日本ブース（ジャパンパビリオン）は在タイ日本国大使館が統括し、本学のほか、日本大使館、情報通信研究機構（NICT）、科学技術振興機構（JST）、日本学術振興会（JSPS）、国際協力機構（JICA）、国際農林水産業研究センター（JIRCAS）、宇宙航空研究開発機構（JAXA）、京都大学、東京科学大学、チュラロンコン大学、折り紙ヒコーキ協会など、学術・研究機関が出展しました。 今回、本学のブースでは大学紹介、全学プロジェクトであるCOI-NEXT、J-PEAKS、SATREPSの活動内容について展示を行いました。SATREPSの展示では、プロジェクトの対象資源であるタイ産のパラゴムノキの種子（ゴム種子）の粉砕体験をしてもらい、多くの小中学生、高校生が種子の殻割に興じ好評でした。 また、これまでの本学の科学技術教育への貢献が高く評価され、高等教育・科学・研究・イノベーション省のSupachai Pathumnakul事務次官より、本学工学研究院の兼橋准教授（SATREPS代表）にトロフィーが授与されました。 引き続き、本学の国際活動を推進してまいります。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.tuat.ac.jp/NEWS/info/20260828_01.html',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','991d1307dd20942f2501587ff952a3d08a9a01163f79366ccdc0e19da1344379','7d4df752c1974aec479a456ce2b80de21d1aba265ce1f0a340cc3208af55fa66',1,1,1,1 FROM sources WHERE root_url='https://www.tuat.ac.jp/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
