INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-94A25DF0D8355C1BA3D5','public_higher_education_research',NULL,'地域共生学研究機構（地域教育研究事業） - 高知県立大学ホームページ','https://www.u-kochi.ac.jp/site/aeru/',NULL,'高知県立大学',NULL,'Japan','Asia','japanese_public_university',NULL,NULL,'2026-10-05T19:41:50.435Z','institutional_primary','ja','地域教育研究センターは、「地域志向教育」の実現を目指し、2012年に設立されました。そして2014年からは、地「域」と大「学」が「共」に「生」きていくことを表す「域学共生」の理念のもと、学生と地域、研究者と地域を結ぶ役割を果たして参りました。 2015年度から始まった「地域学実習」は、毎年、本学の１回生全員が県内で実習させていただいております。現在では、学生が地域の魅力や課題を肌で感じ、自らの専攻と地域社会との関連を考え、主体的な行動を促す重要な科目になっています。 また、地域課題の解決に取り組む学生を支援する教育プログラムとして創設された「立志社中」も、コロナ禍を経て学生活動が再開し、社会的視点を身につけた実行力のある学生および卒業生を輩出しています。 以上のような教育関連事業は、本学および本学学生と直接関わっていただいている自治体や集落の方々のご理解とご協力がなければ成り立ちません。本センターでは、「連携推進会議」「ご意見番会議」を設け、情報共有や意見交換をさせていただくとともに、「域学共生連携拡大会議」も隔年で開催し、大学での研究教育活動を広くご理解いただく取り組みを行っております。 本センター設立以降、これらの活動を支えてくださった県民の皆様・自治体の皆様には、心より感謝申し上げます。 今後も、これらの取り組みをもとに、高知県ひいては社会全体にも貢献する地域教育研究センターを目指します。引き続き、県民の皆様、学内外の皆様のお力添えを賜りますよう、お願い申し上げます。','地域教育研究センターは、「地域志向教育」の実現を目指し、2012年に設立されました。そして2014年からは、地「域」と大「学」が「共」に「生」きていくことを表す「域学共生」の理念のもと、学生と地域、研究者と地域を結ぶ役割を果たして参りました。 2015年度から始まった「地域学実習」は、毎年、本学の１回生全員が県内で実習させていただいております。現在では、学生が地域の魅力や課題を肌で感じ、自らの専攻と地域社会との関連を考え、主体的な行動を促す重要な科目になっています。 また、地域課題の解決に取り組む学生を支援する教育プログラムとして創設された「立志社中」も、コロナ禍を経て学生活動が再開し、社会的視点を身につけた実行力のある学生および卒業生を輩出しています。 以上のような教育関連事業は、本学および本学学生と直接関わっていただいている自治体や集落の方々のご理解とご協力がなければ成り立ちません。本センターでは、「連携推進会議」「ご意見番会議」を設け、情報共有や意見交換をさせていただくとともに、「域学共生連携拡大会議」も隔年で開催し、大学での研究教育活動を広くご理解いただく取り組みを行っております。 本センター設立以降、これらの活動を支えてくださった県民の皆様・自治体の皆様には、心より感謝申し上げます。 今後も、これらの取り組みをもとに、高知県ひいては社会全体にも貢献する地域教育研究センターを目指します。引き続き、県民の皆様、学内外の皆様のお力添えを賜りますよう、お願い申し上げます。',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.u-kochi.ac.jp/site/aeru/',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ef22b1fec37c1ece95e1aebf8901f19864fb1fc5962368ddfa8fa193debae3c6','94a25df0d8355c1ba3d5a599a53f210ad8c3c92b478952a56a3d65782ef2a94e',1,1,1,1 FROM sources WHERE root_url='https://www.u-kochi.ac.jp/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'地域共生学研究機構 地域教育研究事業 - 高知県立大学ホームヘ ーシ 地域教育研究センターは 地域志向教育 の実現を目指し 2012年に設立されました そして2014年からは 地 域 と大 学 か 共 に 生 きていくことを表す 域学共生 の理念のもと 学生と地域 研究者と地域を結ふ 役割を果たして参りました 2015年度から始まった 地域学実習 は 毎年 本学の１回生全員か 県内て 実習させていたた いております 現在て は 学生か 地域の魅力や課題を肌て 感し 自らの専攻と地域社会との関連を考え 主体的な行動を促す重要な科目になっています また 地域課題の解決に取り組む学生を支援する教育フ ロク ラムとして創設された 立志社中 も コロナ禍を経て学生活動か 再開し 社会的視点を身につけた実行力のある学生およひ 卒業生を輩出しています 以上のような教育関連事業は 本学およひ 本学学生と直接関わっていたた いている自治体や集落の方々のこ 理解とこ 協力か なけれは 成り立ちません 本センターて は 連携推進会議 こ 意見番会議 を設け 情報共有や意見交換をさせていたた くとともに 域学共生連携拡大会議 も隔年て 開催し 大学て の研究教育活動を広くこ 理解いたた く取り組みを行っております 本センター設立以降 これらの活動を支えてくた さった県民の皆様 自治体の皆様には 心より感謝申し上け ます 今後も これらの取り組みをもとに 高知県ひいては社会全体にも貢献する地域教育研究センターを目指します 引き続き 県民の皆様 学内外の皆様のお力添えを賜りますよう お願い申し上け ます public higher education research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='94a25df0d8355c1ba3d5a599a53f210ad8c3c92b478952a56a3d65782ef2a94e' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
