INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-4C58A45D8F901F1E685E','research_infrastructure',NULL,'PRACE | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/prace/',NULL,'Data, Computing and Digital Research Infrastructures / Landmark PRACE Partnership for Advanced Computing in Europe',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:28:16.764Z','institutional_primary','en','The Partnership for Advanced Computing in Europe (PRACE) is a supercomputing Research Infrastructure providing access to world-class computing and data management resources and services through a peer-review process, for large-scale highimpact scientific and engineering applications at the highest performance level across all disciplines. PRACE seeks to support the European scientists and engineers to exploit more broadly high-end HPC and to strengthen connection with many ESFRI RIs to maximise the impact on the ERA and on broad applications in industry. PRACE actively interfaces with XSEDE (USA), RIKEN (Japan), Compute Canada, the European data network for the research and education community (GÉANT), the European Grid Infrastructure (EGI), the European Data Infrastructure (EUDAT), and the Human Brain Project (HBP).','The Partnership for Advanced Computing in Europe (PRACE) is a supercomputing Research Infrastructure providing access to world-class computing and data management resources and services through a peer-review process, for large-scale highimpact scientific and engineering applications at the highest performance level across all disciplines. PRACE seeks to support the European scientists and engineers to exploit more broadly high-end HPC and to strengthen connection with many ESFRI RIs to maximise the impact on the ERA and on broad applications in industry. PRACE actively interfaces with XSEDE (USA), RIKEN (Japan), Compute Canada, the European data network for the research and education community (GÉANT), the European Grid Infrastructure (EGI), the European Data Infrastructure (EUDAT), and the Human Brain Project (HBP).',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/prace/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','32342bf71884b5006dac76dd754750a3b2264c17dd99a0e82417037150cd24c6','4c58a45d8f901f1e685e8afa0ef9e196a6a68b320d7f59417cbabe8657ffa0f7',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/prace/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
