INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-955CD0CB7D00AA25EACE','research_infrastructure',NULL,'EBRAINS | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ebrains/',NULL,'Data, Computing and Digital Research Infrastructures / Project EBRAINS European Brain ReseArch INfrastructureS',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:28:16.270Z','institutional_primary','en','The European Brain ReseArch INfrastructureS (EBRAINS) is a distributed Digital Infrastructure at the interface of neuroscience, computing and technology. It is a ‘one-stop-shop’ offering scientists and technology developers the most advanced tools and services for brain research, including FAIR data services, next-generation brain atlasing, simulation platforms and AI-based analysis of big data. EBRAINS catalyses new findings in science, and innovative brain-inspired technologies and computing to help reach a deeper understanding of the human brain. Beyond neuroscience, it will empower a broad spectrum of biomedicine and other research, including work on Covid-19. It should also enable forward-looking, digital applications for industrial and medical use, for the benefit of patients and society.','The European Brain ReseArch INfrastructureS (EBRAINS) is a distributed Digital Infrastructure at the interface of neuroscience, computing and technology. It is a ‘one-stop-shop’ offering scientists and technology developers the most advanced tools and services for brain research, including FAIR data services, next-generation brain atlasing, simulation platforms and AI-based analysis of big data. EBRAINS catalyses new findings in science, and innovative brain-inspired technologies and computing to help reach a deeper understanding of the human brain. Beyond neuroscience, it will empower a broad spectrum of biomedicine and other research, including work on Covid-19. It should also enable forward-looking, digital applications for industrial and medical use, for the benefit of patients and society.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ebrains/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','aad912fe8768e6ac2893d856b8d777b0afece23d62cc6eba8d49c1ff156d083c','955cd0cb7d00aa25eace64871cd059621b4da95641e48aa94e1ace4bf67d1446',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ebrains/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
