INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-1AB402D1C82760FFACA5','research_infrastructure',NULL,'SLICES | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/slices/',NULL,'Data, Computing and Digital Research Infrastructures / Project SLICES Scientific Large-scale Infrastructure for Computing/Communication Experimental Studies',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:28:36.615Z','institutional_primary','en','The Scientific Large-scale Infrastructure for Computing/Communication Experimental Studies (SLICES) is a distributed flexible Digital Infrastructure designed to support large-scale, experimental research focused on networking protocols, radio technologies, services, data collection, parallel and distributed computing and in particular cloud and edge-based computing architectures and services. SLICES will make a fundamental contribution to research and innovation in Digital Sciences and Infrastructures, future Internet technologies, future smart networks and services. This encompasses the full range of network, computing, and storage functions required for ‘ondemand’ services across many verticals, and addresses new complex research challenges, supporting disruptive science in IoT, networks and distributed systems.','The Scientific Large-scale Infrastructure for Computing/Communication Experimental Studies (SLICES) is a distributed flexible Digital Infrastructure designed to support large-scale, experimental research focused on networking protocols, radio technologies, services, data collection, parallel and distributed computing and in particular cloud and edge-based computing architectures and services. SLICES will make a fundamental contribution to research and innovation in Digital Sciences and Infrastructures, future Internet technologies, future smart networks and services. This encompasses the full range of network, computing, and storage functions required for ‘ondemand’ services across many verticals, and addresses new complex research challenges, supporting disruptive science in IoT, networks and distributed systems.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/slices/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a13600106f6ca34d5d2f4563edc743ac16b282d3c222c785f8562968bddc58de','1ab402d1c82760ffaca5acaba70d39760bf8f1ad100c1db2c17ceaa30bec02f9',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/slices/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'slices esfri roadmap 2021 the scientific large-scale infrastructure for computing communication experimental studies slices is a distributed flexible digital infrastructure designed to support large-scale experimental research focused on networking protocols radio technologies services data collection parallel and distributed computing and in particular cloud and edge-based computing architectures and services. slices will make a fundamental contribution to research and innovation in digital sciences and infrastructures future internet technologies future smart networks and services. this encompasses the full range of network computing and storage functions required for ondemand services across many verticals and addresses new complex research challenges supporting disruptive science in iot networks and distributed systems. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='1ab402d1c82760ffaca5acaba70d39760bf8f1ad100c1db2c17ceaa30bec02f9' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9304B22F897DDCD86447','research_infrastructure',NULL,'SoBigData | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/sobigdata/',NULL,'Data, Computing and Digital Research Infrastructures / Project SoBigData++ European Integrated Infrastructure for Social Mining and Big Data Analytics',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:28:35.062Z','institutional_primary','en','The European Integrated Infrastructure for Social Mining and Big Data Analytics (SoBigData++) is a distributed and multidisciplinary Research Infrastructure for big social data analytics that, coupled with the consolidation of a cross-disciplinary European research community, is aiming at using social mining and big data to understand the complexity of our contemporary, globally-interconnected society. SoBigData++ offers a distributed platform of interoperable social data mining tools, methodologies and services for obtaining, analyzing, and visualizing massive datasets. The SoBigData++ RI will render social mining experiments more efficiently designed and repeatable by leveraging concrete tools that include ethics, values and norms for privacy, fairness, transparency, and pluralism.','The European Integrated Infrastructure for Social Mining and Big Data Analytics (SoBigData++) is a distributed and multidisciplinary Research Infrastructure for big social data analytics that, coupled with the consolidation of a cross-disciplinary European research community, is aiming at using social mining and big data to understand the complexity of our contemporary, globally-interconnected society. SoBigData++ offers a distributed platform of interoperable social data mining tools, methodologies and services for obtaining, analyzing, and visualizing massive datasets. The SoBigData++ RI will render social mining experiments more efficiently designed and repeatable by leveraging concrete tools that include ethics, values and norms for privacy, fairness, transparency, and pluralism.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/sobigdata/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','bfd4db035e6497d0d30fc212803105a678af3cf4ca6c1d10c566e029df5e9046','9304b22f897ddcd86447e351b3521e22f0825d10912316f8c6d09b7213c2f639',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/sobigdata/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
