INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-763DA9FE9AE6BE027E4A','research_infrastructure',NULL,'ECCSEL ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eccsel-eric/',NULL,'Energy / Landmark ECCSEL ERIC European Carbon Dioxide Capture and Storage Laboratory Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:30:47.660Z','institutional_primary','en','The European Carbon Dioxide Capture and Storage Laboratory Infrastructure (ECCSEL) is a distributed Research Infrastructure with the aim to enhance European science, technology development, innovation and education in the field of Carbon Dioxide Capture, Utilisation, Transport and Storage (CCUS). Its vision is to enable low to zero CO 2 emissions from industry and power generation to combat climate change. ECCSEL provides coordination, operation, development and open access to world-class CCUS research facilities across Europe, covering the whole CCUS value chain: membranes, integrated CCUS systems, pressure/injection, migration, security/troubleshooting, CO 2 pipeline transport and integrity, shipping of CO 2 , smart integrations with carbon capture and re-use into valuable products.','The European Carbon Dioxide Capture and Storage Laboratory Infrastructure (ECCSEL) is a distributed Research Infrastructure with the aim to enhance European science, technology development, innovation and education in the field of Carbon Dioxide Capture, Utilisation, Transport and Storage (CCUS). Its vision is to enable low to zero CO 2 emissions from industry and power generation to combat climate change. ECCSEL provides coordination, operation, development and open access to world-class CCUS research facilities across Europe, covering the whole CCUS value chain: membranes, integrated CCUS systems, pressure/injection, migration, security/troubleshooting, CO 2 pipeline transport and integrity, shipping of CO 2 , smart integrations with carbon capture and re-use into valuable products.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eccsel-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','210c54440182483133b4ccd9ad69a64de2db39cb5c4d53f2c6d874738a0b811b','763da9fe9ae6be027e4ace194645f8fbf5e196a395d578a9e65e2a3b8d112c95',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eccsel-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
