INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-0FED528696C1D9188ADC','research_infrastructure',NULL,'EU-SOLARIS | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eu-solaris/',NULL,'Energy / Landmark EU-SOLARIS European Solar Research Infrastructure for Concentrated Solar Power',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:30:53.632Z','institutional_primary','en','The European Solar Research Infrastructure for Concentrated Solar Power (EU-SOLARIS) is a distributed Research Infrastructure for the integration and coordination of Research and Technology Development (RTD) capabilities and efforts in Concentrating Solar Power/Solar Thermal Energy (CSP/STE) technologies in Europe. EU-SOLARIS will become the reference for CSP/STE and maintain Europe at the forefront of these technologies by facilitating the access of researchers to the most complete, high-quality scientific portfolio of facilities, services and tools via a single access point. EU-SOLARIS will link scientific communities and industry and speed up the development of research and innovation due to a closer collaboration model, knowledge exchange management and a wider dissemination of results.','The European Solar Research Infrastructure for Concentrated Solar Power (EU-SOLARIS) is a distributed Research Infrastructure for the integration and coordination of Research and Technology Development (RTD) capabilities and efforts in Concentrating Solar Power/Solar Thermal Energy (CSP/STE) technologies in Europe. EU-SOLARIS will become the reference for CSP/STE and maintain Europe at the forefront of these technologies by facilitating the access of researchers to the most complete, high-quality scientific portfolio of facilities, services and tools via a single access point. EU-SOLARIS will link scientific communities and industry and speed up the development of research and innovation due to a closer collaboration model, knowledge exchange management and a wider dissemination of results.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eu-solaris/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','16c62aeb0f3bfcdd5eb305f5a86ba681c84e45980811462190cfb51e1c35429f','0fed528696c1d9188adc899b18670d7f2d3cab63b723caa05bf7b5866028c2bf',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eu-solaris/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
