INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-597DB1FB622F04217728','research_infrastructure',NULL,'JHR | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/jhr/',NULL,'Energy / Landmark JHR Jules Horowitz Reactor',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:30:51.429Z','institutional_primary','en','The Jules Horowitz Reactor (JHR) is a reference user facility to observe and understand material and fuel behaviour in extreme nuclear environment by reproducing the operational condition of the different power reactor technologies. JHR will be key for the nuclear international community by extending performances and assessing safety for nuclear power plants, also strengthening technology credibility and public acceptance. JHR will be effective in training new generations of scientists and engineers in the strategic field of nuclear energy also guaranteeing the high level of expertise needed in the staff of power plants in all steps of their lifecycle. JHR will also ensure the production of radioelements for nuclear medicine and for non-nuclear industry.','The Jules Horowitz Reactor (JHR) is a reference user facility to observe and understand material and fuel behaviour in extreme nuclear environment by reproducing the operational condition of the different power reactor technologies. JHR will be key for the nuclear international community by extending performances and assessing safety for nuclear power plants, also strengthening technology credibility and public acceptance. JHR will be effective in training new generations of scientists and engineers in the strategic field of nuclear energy also guaranteeing the high level of expertise needed in the staff of power plants in all steps of their lifecycle. JHR will also ensure the production of radioelements for nuclear medicine and for non-nuclear industry.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/jhr/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','93068baa20afd6f5bc23bd0abc3e9aefb4a5b2d7c6b78e5ac807eb181e93ff40','597db1fb622f042177283d40a1b82fe013f10951ecd1797ffa9fdf1522422fef',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/jhr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
