INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-3CEF7A4E0BA6BF4588F4','research_infrastructure',NULL,'IFMIF-DONES | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ifmif-dones/',NULL,'Energy / Project IFMIF-DONES International Fusion Materials Irradiation facility - DEMO Oriented NEutron Source',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:10.940Z','institutional_primary','en','The International Fusion Materials Irradiation Facility – Demo Oriented NEutron Source (IFMIF-DONES) is a single-sited Research Infrastructure for testing, validation and qualification of the materials to be used in a fusion reactor. It is based on a unique neutron source with energy spectrum and flux tuned to those expected for the first wall containing future fusion reactors. The IFMIF-DONES will be a major step towards IFMIF as it will develop a unique high-current high-duty cycle accelerator technology, liquid metal target technology and advanced control systems. The facility will also offer unique experimental opportunities in other scientific and technology areas including nuclear physics, astrophysics, medical and industrial applications.','The International Fusion Materials Irradiation Facility – Demo Oriented NEutron Source (IFMIF-DONES) is a single-sited Research Infrastructure for testing, validation and qualification of the materials to be used in a fusion reactor. It is based on a unique neutron source with energy spectrum and flux tuned to those expected for the first wall containing future fusion reactors. The IFMIF-DONES will be a major step towards IFMIF as it will develop a unique high-current high-duty cycle accelerator technology, liquid metal target technology and advanced control systems. The facility will also offer unique experimental opportunities in other scientific and technology areas including nuclear physics, astrophysics, medical and industrial applications.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ifmif-dones/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e4bffc79c6f6ee13795ab644626dbc5a7b0bd0c4e766fa89a1bec1efa0f0d357','3cef7a4e0ba6bf4588f4b333207c3d529678e6c91311392be43dc1f816a5d5bf',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ifmif-dones/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
