INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-DBC82619CE62F6D65102','research_infrastructure',NULL,'MARINERG-i | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/marinerg-i/',NULL,'Energy / Project MARINERG-i Marine Renewable Energy Research Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:30:56.213Z','institutional_primary','en','The Marine Renewable Energy Research Infrastructure (MARINERG-i) is a distributed Research Infrastructure composed of a network of test facilities with the critical mass of expertise and world-class equipment to support the design and advancement of the Offshore Renewable Energy (ORE) systems. This involves interdisciplinary research in hydrodynamics, aerodynamics and fluid-structure interaction, material science, electro-technical engineering, ICT, naval architecture, sensors, oceanography, environmental and social sciences, business management, economics and legal sciences. It will accelerate the research development of wave, tidal, offshore wind and combined energy technologies to maintain Europe a global leader in constantly evolving industry.','The Marine Renewable Energy Research Infrastructure (MARINERG-i) is a distributed Research Infrastructure composed of a network of test facilities with the critical mass of expertise and world-class equipment to support the design and advancement of the Offshore Renewable Energy (ORE) systems. This involves interdisciplinary research in hydrodynamics, aerodynamics and fluid-structure interaction, material science, electro-technical engineering, ICT, naval architecture, sensors, oceanography, environmental and social sciences, business management, economics and legal sciences. It will accelerate the research development of wave, tidal, offshore wind and combined energy technologies to maintain Europe a global leader in constantly evolving industry.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/marinerg-i/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e4cef3924a11ec50f05488d86939fda52528bb5847129099e4a3bcfb6bccbd8e','dbc82619ce62f6d65102b75dab7d7dbe8010b9c1c5b563dff134d2f79fcae612',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/marinerg-i/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
