INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E1FE6D5191D86096C310','research_infrastructure',NULL,'ACTRIS | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/actris/',NULL,'Environment / Landmark ACTRIS Aerosol, Clouds and Trace Gases Research Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:15.510Z','institutional_primary','en','The Aerosol, Clouds and Trace Gases Research Infrastructure (ACTRIS) is a distributed RI dedicated to high-quality observation of aerosol, clouds, trace gases and exploration of their interactions. ACTRIS delivers precision data, innovative services, and procedures regarding the 4D variability and the physical, optical and chemical properties of short-lived atmospheric constituents. It improves the current capacity to understand and predict past, current and future evolution of the atmospheric environment. ACTRIS serves a vast community of users working with observations, experiments, models, satellite data, analysis and predicting systems. It offers access to advanced technological platforms to explore atmospheric processes crucial for monitoring air quality and understanding climate change.','The Aerosol, Clouds and Trace Gases Research Infrastructure (ACTRIS) is a distributed RI dedicated to high-quality observation of aerosol, clouds, trace gases and exploration of their interactions. ACTRIS delivers precision data, innovative services, and procedures regarding the 4D variability and the physical, optical and chemical properties of short-lived atmospheric constituents. It improves the current capacity to understand and predict past, current and future evolution of the atmospheric environment. ACTRIS serves a vast community of users working with observations, experiments, models, satellite data, analysis and predicting systems. It offers access to advanced technological platforms to explore atmospheric processes crucial for monitoring air quality and understanding climate change.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/actris/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','19ff4aca53cb8d348c916e911b33a9df2a021b81e164c5736c7d84238f1b7478','e1fe6d5191d86096c310972570fd82efd47090d7573666aba3828bc1edb9872e',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/actris/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'actris esfri roadmap 2021 the aerosol clouds and trace gases research infrastructure actris is a distributed ri dedicated to high-quality observation of aerosol clouds trace gases and exploration of their interactions. actris delivers precision data innovative services and procedures regarding the 4d variability and the physical optical and chemical properties of short-lived atmospheric constituents. it improves the current capacity to understand and predict past current and future evolution of the atmospheric environment. actris serves a vast community of users working with observations experiments models satellite data analysis and predicting systems. it offers access to advanced technological platforms to explore atmospheric processes crucial for monitoring air quality and understanding climate change. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='e1fe6d5191d86096c310972570fd82efd47090d7573666aba3828bc1edb9872e' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-97105943E3ACD553DAAA','research_infrastructure',NULL,'EMSO ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/emso-eric/',NULL,'Environment / Landmark EMSO ERIC European Multidisciplinary Seafloor and water-column Observatory',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:16.623Z','institutional_primary','en','The European Multidisciplinary Seafloor and water-column Observatory (EMSO) is a distributed Research Infrastructure aiming at exploring the oceans to gain a better understanding of phenomena happening within and below them, and to explain the critical role that these phenomena play in the broader Earth system. EMSO offers high-quality environmental data and services covering a multi- and inter-disciplinary range of research areas including biology, geology, chemistry, physics, engineering and computer science, from polar to tropical environments. EMSO provides these data to a large and diverse group of users, from scientists and industries to institutions and policy makers to support the definition of environmental policies and respond to pressing scientific and societal challenges.','The European Multidisciplinary Seafloor and water-column Observatory (EMSO) is a distributed Research Infrastructure aiming at exploring the oceans to gain a better understanding of phenomena happening within and below them, and to explain the critical role that these phenomena play in the broader Earth system. EMSO offers high-quality environmental data and services covering a multi- and inter-disciplinary range of research areas including biology, geology, chemistry, physics, engineering and computer science, from polar to tropical environments. EMSO provides these data to a large and diverse group of users, from scientists and industries to institutions and policy makers to support the definition of environmental policies and respond to pressing scientific and societal challenges.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/emso-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','06135fd59cc9f823966a9638ee5875eb8bab047e44ebdafede74f7a948faa2f0','97105943e3acd553daaabc8efd593c867a4627a82e85895b763bc50ed56f4201',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/emso-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
