INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9D6D010F967702C14924','research_infrastructure',NULL,'EPOS ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/epos-eric/',NULL,'Environment / Landmark EPOS ERIC European Plate Observing System',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:17.356Z','institutional_primary','en','The European Plate Observing System (EPOS) is a multidisciplinary, distributed Research Infrastructure that facilitates the integrated use of data, data products, and facilities from the solid Earth science community in Europe. EPOS will enable innovative multidisciplinary research for a better understanding of the Earth’s physical and chemical processes that control earthquakes, volcanic eruptions, ground instability and tsunamis as well as the processes driving tectonics and Earth’s surface dynamics. Through integration of data, models and facilities, EPOS will allow the Earth science community to make a step change in developing new concepts and tools for key answers to scientific and socio-economic questions concerning geo-hazards and georesources for a safe and sustainable society.','The European Plate Observing System (EPOS) is a multidisciplinary, distributed Research Infrastructure that facilitates the integrated use of data, data products, and facilities from the solid Earth science community in Europe. EPOS will enable innovative multidisciplinary research for a better understanding of the Earth’s physical and chemical processes that control earthquakes, volcanic eruptions, ground instability and tsunamis as well as the processes driving tectonics and Earth’s surface dynamics. Through integration of data, models and facilities, EPOS will allow the Earth science community to make a step change in developing new concepts and tools for key answers to scientific and socio-economic questions concerning geo-hazards and georesources for a safe and sustainable society.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/epos-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','faa8bcf8368d200d5d18130c3743c482e0a2167b1b0ecc097c03618886dbab35','9d6d010f967702c14924682b5cfb71feb75fc85a7fb223b63b4c36e207c6cb5c',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/epos-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
