INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-800EEC01A7BE3FCE381D','research_infrastructure',NULL,'EURO-ARGO ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/euro-argo-eric/',NULL,'Environment / Landmark EURO-ARGO ERIC European contribution to the international Argo Programme',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:17.768Z','institutional_primary','en','The European contribution to the International Argo Programme (EURO-ARGO) is a distributed Research Infrastructure that organizes and federates the European contribution to the Argo international programme for in situ ocean observations. EUROARGO provides enhanced coverage in the European regional seas by deploying and operating an array of around 800 floats corresponding to ¼ of the global Argo array of profiling floats which measure temperature and salinity every 10 days throughout the deep global oceans. It delivers data both in real-time and delayed mode for climate change research and monitoring as well as operational services such as Copernicus. It also aims at developing the new phase of Argo extending the network to abyssal oceans, biogeochemical parameters, marginal seas and high latitudes.','The European contribution to the International Argo Programme (EURO-ARGO) is a distributed Research Infrastructure that organizes and federates the European contribution to the Argo international programme for in situ ocean observations. EUROARGO provides enhanced coverage in the European regional seas by deploying and operating an array of around 800 floats corresponding to ¼ of the global Argo array of profiling floats which measure temperature and salinity every 10 days throughout the deep global oceans. It delivers data both in real-time and delayed mode for climate change research and monitoring as well as operational services such as Copernicus. It also aims at developing the new phase of Argo extending the network to abyssal oceans, biogeochemical parameters, marginal seas and high latitudes.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/euro-argo-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','fbb613cd4ed8d2c39353736a9d52b9f9f3e62dcfdbf6bc3d4b76dec6068ae2f3','800eec01a7be3fce381db06f22c08fe67bee40aeeb2ce6dccbe9f4810e30495e',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/euro-argo-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'euro-argo eric esfri roadmap 2021 the european contribution to the international argo programme euro-argo is a distributed research infrastructure that organizes and federates the european contribution to the argo international programme for in situ ocean observations. euroargo provides enhanced coverage in the european regional seas by deploying and operating an array of around 800 floats corresponding to ¼ of the global argo array of profiling floats which measure temperature and salinity every 10 days throughout the deep global oceans. it delivers data both in real-time and delayed mode for climate change research and monitoring as well as operational services such as copernicus. it also aims at developing the new phase of argo extending the network to abyssal oceans biogeochemical parameters marginal seas and high latitudes. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='800eec01a7be3fce381db06f22c08fe67bee40aeeb2ce6dccbe9f4810e30495e' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-980FC4789322453941CD','research_infrastructure',NULL,'IAGOS | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/iagos/',NULL,'Environment / Landmark IAGOS In-service Aircraft for a Global Observing System',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:17.764Z','institutional_primary','en','The In-service Aircraft for a Global Observing System (IAGOS) is a distributed Research Infrastructure that operates a global-scale monitoring system for atmospheric trace gases, aerosols and clouds by using the existing provisions of the global air transport system to provide essential data on climate change and air quality. It complements the global observing system in addition to ground-based networks, dedicated research campaigns and observations from satellites, balloons, and ships. In order to provide optimal information, two complementary systems have been implemented, (i) IAGOS-CORE providing global coverage on a day-to-day basis of key observables and (ii) IAGOS-CARIBIC offering a more in-depth and complex set of observations with lesser geographical and temporal coverage.','The In-service Aircraft for a Global Observing System (IAGOS) is a distributed Research Infrastructure that operates a global-scale monitoring system for atmospheric trace gases, aerosols and clouds by using the existing provisions of the global air transport system to provide essential data on climate change and air quality. It complements the global observing system in addition to ground-based networks, dedicated research campaigns and observations from satellites, balloons, and ships. In order to provide optimal information, two complementary systems have been implemented, (i) IAGOS-CORE providing global coverage on a day-to-day basis of key observables and (ii) IAGOS-CARIBIC offering a more in-depth and complex set of observations with lesser geographical and temporal coverage.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/iagos/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','41aa0cf6d6feee713e9a73e8879f37f7619479a3114598acf53d6974dcb122d1','980fc4789322453941cd595e0163eb0e31703400af1e0cd90724b75ebe883f12',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/iagos/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
