INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-378C86039D0B889B17D5','research_infrastructure',NULL,'ICOS ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/icos-eric/',NULL,'Environment / Landmark ICOS ERIC Integrated Carbon Observation System',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:18.506Z','institutional_primary','en','The Integrated Carbon Observation System (ICOS) is a distributed Research Infrastructure to facilitate research on carbon cycle and to provide necessary information on greenhouse gases (GHG). ICOS conducts long-term observations in the atmosphere, ecosystems, and oceans, and generates high-precision and stardardised data to monitor the present state and extrapolate the future behaviour of the global carbon cycle and GHG fluxes in order to predict environment changes and mitigate their impacts. ICOS helps to elaborate an account of the Earth system and its response to climate change and other environmental challenges. ICOS advances the fulfilment of the United Nations’ Sustainable Development Goals and the European Union’s Societal Challenges, especially those concerning climate change.','The Integrated Carbon Observation System (ICOS) is a distributed Research Infrastructure to facilitate research on carbon cycle and to provide necessary information on greenhouse gases (GHG). ICOS conducts long-term observations in the atmosphere, ecosystems, and oceans, and generates high-precision and stardardised data to monitor the present state and extrapolate the future behaviour of the global carbon cycle and GHG fluxes in order to predict environment changes and mitigate their impacts. ICOS helps to elaborate an account of the Earth system and its response to climate change and other environmental challenges. ICOS advances the fulfilment of the United Nations’ Sustainable Development Goals and the European Union’s Societal Challenges, especially those concerning climate change.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/icos-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3da672fc5a4ef458b422c8ee7a82819e669df1d9e3f9b9f31a4f3523436719dc','378c86039d0b889b17d57038d0557a7bf6fc77969521f0c36f2c7ffb8553e08a',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/icos-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'icos eric esfri roadmap 2021 the integrated carbon observation system icos is a distributed research infrastructure to facilitate research on carbon cycle and to provide necessary information on greenhouse gases ghg . icos conducts long-term observations in the atmosphere ecosystems and oceans and generates high-precision and stardardised data to monitor the present state and extrapolate the future behaviour of the global carbon cycle and ghg fluxes in order to predict environment changes and mitigate their impacts. icos helps to elaborate an account of the earth system and its response to climate change and other environmental challenges. icos advances the fulfilment of the united nations sustainable development goals and the european union s societal challenges especially those concerning climate change. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='378c86039d0b889b17d57038d0557a7bf6fc77969521f0c36f2c7ffb8553e08a' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-EB0AFDB318854571458F','research_infrastructure',NULL,'LifeWatch ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/lifewatch-eric/',NULL,'Environment / Landmark LifeWatch ERIC e-Infrastructure for Biodiversity and Ecosystem Research',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:29.502Z','institutional_primary','en','The e-Infrastructure for Biodiversity and Ecosystem Research (LifeWatch) is a distributed Research Infrastructure providing e-Science facilities and services to the biodiversity and ecosystem research community. LifeWatch ERIC seeks to understand the complex interactions between species and the environment, taking advantage of High-Performance, Grid and Big Data computing systems, and the development of advanced modelling tools to implement measures aimed at preserving life on Earth. LifeWatch tackles the constraints affecting biodiversity and ecosystem research, such as the pressing need for increasingly diverse data, larger and more advanced models, open data and open science clouds, thus allowing to explore new frontiers in ecological science and support society in addressing global challenges.','The e-Infrastructure for Biodiversity and Ecosystem Research (LifeWatch) is a distributed Research Infrastructure providing e-Science facilities and services to the biodiversity and ecosystem research community. LifeWatch ERIC seeks to understand the complex interactions between species and the environment, taking advantage of High-Performance, Grid and Big Data computing systems, and the development of advanced modelling tools to implement measures aimed at preserving life on Earth. LifeWatch tackles the constraints affecting biodiversity and ecosystem research, such as the pressing need for increasingly diverse data, larger and more advanced models, open data and open science clouds, thus allowing to explore new frontiers in ecological science and support society in addressing global challenges.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/lifewatch-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','29cb00b8ebe75b3a0c5ee211a4b6d8673d93cd566a6501806f1ab756b96e4e64','eb0afdb318854571458f99b8a9cdde2392d52ebfb74cce5623b6ec9d48e764cc',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/lifewatch-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'lifewatch eric esfri roadmap 2021 the e-infrastructure for biodiversity and ecosystem research lifewatch is a distributed research infrastructure providing e-science facilities and services to the biodiversity and ecosystem research community. lifewatch eric seeks to understand the complex interactions between species and the environment taking advantage of high-performance grid and big data computing systems and the development of advanced modelling tools to implement measures aimed at preserving life on earth. lifewatch tackles the constraints affecting biodiversity and ecosystem research such as the pressing need for increasingly diverse data larger and more advanced models open data and open science clouds thus allowing to explore new frontiers in ecological science and support society in addressing global challenges. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='eb0afdb318854571458f99b8a9cdde2392d52ebfb74cce5623b6ec9d48e764cc' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B520438BD3BD05D2A3B2','research_infrastructure',NULL,'DANUBIUS-RI | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/danubius-ri/',NULL,'Environment / Project DANUBIUS-RI International Centre for Advanced Studies on River-Sea Systems',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:28.950Z','institutional_primary','en','The International Centre for Advanced Studies on River-Sea Systems (DANUBIUS-RI) is a distributed Research Infrastructure to enable excellent interdisciplinary research and innovation on River-Sea Systems (RSS). Building on existing expertise spanning the environmental, social and economic sciences, it aims to provide an integrated Research Infrastructure for remote and in situ observation systems, experimental facilities, laboratories, modelling tools and resources for knowledge exchange along freshwater-seawater continua throughout Europe, from river source to coastal sea. DANUBIUS-RI will provide solutions to societal risks and challenges arising from global and climate change, and extreme events, offering a source to sea perspective to resolve the problems of adverse human impacts.','The International Centre for Advanced Studies on River-Sea Systems (DANUBIUS-RI) is a distributed Research Infrastructure to enable excellent interdisciplinary research and innovation on River-Sea Systems (RSS). Building on existing expertise spanning the environmental, social and economic sciences, it aims to provide an integrated Research Infrastructure for remote and in situ observation systems, experimental facilities, laboratories, modelling tools and resources for knowledge exchange along freshwater-seawater continua throughout Europe, from river source to coastal sea. DANUBIUS-RI will provide solutions to societal risks and challenges arising from global and climate change, and extreme events, offering a source to sea perspective to resolve the problems of adverse human impacts.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/danubius-ri/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c8ea5103ab140a10d50924306e8dfdfa13a8dc7bed0128ad3e45e42984cc4c30','b520438bd3bd05d2a3b20370b10b7f6930a25b17277e4ca9e6f031d34b2b3095',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/danubius-ri/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
