INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-5139BB6F17282473D323','research_infrastructure',NULL,'DiSSCo | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/dissco/',NULL,'Environment / Project DiSSCo Distributed System of Scientific Collections',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:29.780Z','institutional_primary','en','The Distributed System of Scientific Collections (DiSSCo) is a distributed word-class Research Infrastructure to integrate European Natural Science Collections (NSCs) for data-intensive research and innovation in environment, food security, health, and bioeconomy. The DiSSCo RI aims to digitally unifies all European natural science assets under common access, curation, policies and practices that ensure that all the data is easily Findable, Accessible, Interoperable and Reusable (FAIR principles). By mobilising, harmonising and providing Natural Science Collections data, DiSSCo fills a significant gap in the value chain of European RIs because it provides a fundamental basis of knowledge at the scale and precision required to enable research for tackling grand societal challenges.','The Distributed System of Scientific Collections (DiSSCo) is a distributed word-class Research Infrastructure to integrate European Natural Science Collections (NSCs) for data-intensive research and innovation in environment, food security, health, and bioeconomy. The DiSSCo RI aims to digitally unifies all European natural science assets under common access, curation, policies and practices that ensure that all the data is easily Findable, Accessible, Interoperable and Reusable (FAIR principles). By mobilising, harmonising and providing Natural Science Collections data, DiSSCo fills a significant gap in the value chain of European RIs because it provides a fundamental basis of knowledge at the scale and precision required to enable research for tackling grand societal challenges.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/dissco/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','45834e3c75630f69cd025d11225df00abc624f39ea5b60fa4b8add632687c328','5139bb6f17282473d32333d13721199659251cbc838e0c086ac3b8ffb8b6a5b9',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/dissco/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
