INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2E35209D92380CD90056','research_infrastructure',NULL,'eLTER RI | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/elter-ri/',NULL,'Environment / Project eLTER RI Integrated European Long-Term Ecosystem, critical zone and socio-ecological system Research Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:29.107Z','institutional_primary','en','The Integrated European Long-Term Ecosystem, critical zone and socio-ecological system Research Infrastructure (eLTER RI) is a distributed RI to facilitate high impact research and catalyse new insights about the compounded impacts of climate change, biodiversity loss, soil degradation, pollution, and unsustainable resource use on a range of European socio-ecological systems. eLTER RI aspires to develop the scientific capacity to improve the understanding of terrestrial, freshwater, and transitional water ecosystems. Combined with socio-ecological approach to studying integrated human-nature systems and commitment to integrating stakeholder knowledge, it provides a solid foundation to inform policy-maker systems to find evidencebased sustainable solutions for addressing current and emerging challenges.','The Integrated European Long-Term Ecosystem, critical zone and socio-ecological system Research Infrastructure (eLTER RI) is a distributed RI to facilitate high impact research and catalyse new insights about the compounded impacts of climate change, biodiversity loss, soil degradation, pollution, and unsustainable resource use on a range of European socio-ecological systems. eLTER RI aspires to develop the scientific capacity to improve the understanding of terrestrial, freshwater, and transitional water ecosystems. Combined with socio-ecological approach to studying integrated human-nature systems and commitment to integrating stakeholder knowledge, it provides a solid foundation to inform policy-maker systems to find evidencebased sustainable solutions for addressing current and emerging challenges.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/elter-ri/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','88aedee6cefbf52933dd6f6b94119f004229ac26705888420d8d54b99c077fc4','2e35209d92380cd900564750590a1570209b61c5b9d57ab29ef721fda01a0c83',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/elter-ri/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
