INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-8F002992F3E1E52A706D','research_infrastructure',NULL,'AnaEE | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/anaee/',NULL,'Health & Food / Landmark AnaEE Analysis and Experimentation on Ecosystems',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:45.567Z','institutional_primary','en','The Analysis and Experimentation on Ecosystems (AnaEE) is a distributed Research Infrastructure which provides integrated and coordinated management of experimental, analytical and modelling facilities, with the aim to support scientists in testing the potential impacts of climate change and land use in Europe. Characteristic to AnaEE are its versatile facilities that can simulate environmental drivers ranging from land-use change, pollution, biological invasions, rising atmospheric greenhouse gases concentrations, to increasing extreme events such as droughts and heatwaves. AnaEE will forge evidence-based adaptation and mitigation strategies to maintain essential services to society including carbon sequestration, food security, clean water, biodiversity and ecosystem health today and in the future.','The Analysis and Experimentation on Ecosystems (AnaEE) is a distributed Research Infrastructure which provides integrated and coordinated management of experimental, analytical and modelling facilities, with the aim to support scientists in testing the potential impacts of climate change and land use in Europe. Characteristic to AnaEE are its versatile facilities that can simulate environmental drivers ranging from land-use change, pollution, biological invasions, rising atmospheric greenhouse gases concentrations, to increasing extreme events such as droughts and heatwaves. AnaEE will forge evidence-based adaptation and mitigation strategies to maintain essential services to society including carbon sequestration, food security, clean water, biodiversity and ecosystem health today and in the future.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/anaee/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','37d4eeb2217a86bac797c7e709d6560df2ec7d16e623192435f94fbc2756d8eb','8f002992f3e1e52a706d90696595010fa5def6fc14fddfd66465581264575b35',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/anaee/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
