INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-805F2F8B453542F9BB8A','research_infrastructure',NULL,'BBMRI ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/bbmri-eric/',NULL,'Health & Food / Landmark BBMRI ERIC Biobanking and BioMolecular Resources Research Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:00.945Z','institutional_primary','en','The Biobanking and BioMolecular resources Research Infrastructure (BBMRI) is one of the largest Research Infrastructures for biobanking in Europe. BBMRI brings together main players from the biobanking field – researchers, biobankers, industry, and patients – to boost biomedical research and ultimately to make new treatments possible. BBMRI improves the accessibility and interoperability of existing comprehensive collections, either population-based or clinical-oriented, of biological samples from different (sub-)populations of Europe or rare diseases. These collections include the associated data on factors such as health status, nutrition, lifestyle and environmental exposure of the study subjects. BBMRI also offers quality management services and support with ethical, legal and societal issues.','The Biobanking and BioMolecular resources Research Infrastructure (BBMRI) is one of the largest Research Infrastructures for biobanking in Europe. BBMRI brings together main players from the biobanking field – researchers, biobankers, industry, and patients – to boost biomedical research and ultimately to make new treatments possible. BBMRI improves the accessibility and interoperability of existing comprehensive collections, either population-based or clinical-oriented, of biological samples from different (sub-)populations of Europe or rare diseases. These collections include the associated data on factors such as health status, nutrition, lifestyle and environmental exposure of the study subjects. BBMRI also offers quality management services and support with ethical, legal and societal issues.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/bbmri-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','df836d05e5c76cb66a4a04d50fffc403ab2d5c6881a07c574cf3b0788685d98f','805f2f8b453542f9bb8af572d7357b7f8cc363dbeeb5ed338eec185c146bf8e1',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/bbmri-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
