INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B739BD76BD7EFDBCB5A1','research_infrastructure',NULL,'EATRIS ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eatris-eric/',NULL,'Health & Food / Landmark EATRIS ERIC European Advanced Translational Research Infrastructure in Medicine',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:59.684Z','institutional_primary','en','The European Advanced Translational Research Infrastructure in Medicine (EATRIS) is a distributed Research Infrastructure for translational medicine. EATRIS brings together resources and services to support researchers in developing their biomedical discoveries into novel translational tools and interventions for better health outcomes. EATRIS provides access to crossdisciplinary expertise and cutting-edge technologies to successfully move early-stage research for drug development, ranging from scientific equipment, knowledge-based resources from sample collections to GMP manufacturing and regulatory guidance, closer to the patient. Research services and medicines development expertise are provided in advanced therapy medicinal products, biomarkers, imaging and tracing, small molecules and vaccines.','The European Advanced Translational Research Infrastructure in Medicine (EATRIS) is a distributed Research Infrastructure for translational medicine. EATRIS brings together resources and services to support researchers in developing their biomedical discoveries into novel translational tools and interventions for better health outcomes. EATRIS provides access to crossdisciplinary expertise and cutting-edge technologies to successfully move early-stage research for drug development, ranging from scientific equipment, knowledge-based resources from sample collections to GMP manufacturing and regulatory guidance, closer to the patient. Research services and medicines development expertise are provided in advanced therapy medicinal products, biomarkers, imaging and tracing, small molecules and vaccines.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eatris-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','5ecd7aae75a70e1755da2030cedf5293824f0be086dcd5c9291869c17078574c','b739bd76bd7efdbcb5a10eb7571bb1c0d6b5bd771bb3f696831c8b37caedfe65',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eatris-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
