INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-86FDFA1382AEC7F34A4C','research_infrastructure',NULL,'ECRIN ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ecrin-eric/',NULL,'Health & Food / Landmark ECRIN ERIC European Clinical Research Infrastructure Network',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:31:59.681Z','institutional_primary','en','The European Clinical Research Infrastructure Network (ECRIN) is a distributed Research Infrastructure that supports the preparation and implementation of multinational, high-quality, transparent clinical trials thus overcoming the obstacles caused by fragmentation and poor interoperability of the national, clinical research environment in Europe. Support areas include the preparation of applications for funding, protocol evaluation, trial management, quality assurance and addressing regulatory and ethical issues. ECRIN creates added value through access to expertise and patients, increasing the reach, diversity, and result quality of clinical trials. It fulfils the vision of a society where all decisions in medical practice are based on sound scientific evidence from high-quality clinical research.','The European Clinical Research Infrastructure Network (ECRIN) is a distributed Research Infrastructure that supports the preparation and implementation of multinational, high-quality, transparent clinical trials thus overcoming the obstacles caused by fragmentation and poor interoperability of the national, clinical research environment in Europe. Support areas include the preparation of applications for funding, protocol evaluation, trial management, quality assurance and addressing regulatory and ethical issues. ECRIN creates added value through access to expertise and patients, increasing the reach, diversity, and result quality of clinical trials. It fulfils the vision of a society where all decisions in medical practice are based on sound scientific evidence from high-quality clinical research.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ecrin-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','9dfddf9b8922c555125884f4d0c1ed508eea177085acf86473451e5138aaedfa','86fdfa1382aec7f34a4cd07e9269a2c4d1ba6b197b0e12dba22fc9ff37765248',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ecrin-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
