INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-FF33BED4CFA7FC3AEC79','research_infrastructure',NULL,'ELIXIR | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/elixir/',NULL,'Health & Food / Landmark ELIXIR A distributed infrastructure for life-science information',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:01.027Z','institutional_primary','en','The distributed infrastructure for life-science data (ELIXIR) is a unique initiative that brings together Europe’s leading life science organisations in managing and safeguarding the increasing volume of data being generated by publicly funded research. It coordinates, integrates and sustains bioinformatics resources across European countries and enables users in academia and industry to access services that are vital for their research. ELIXIR makes it easier for scientists to find and share data, exchange expertise, and agree on best practices and will help them gain new insights into how living organisms work. Ultimately, ELIXIR helps address the Grand Challenges across life sciences, from marine research – via plants and agriculture – to health research and medical sciences.','The distributed infrastructure for life-science data (ELIXIR) is a unique initiative that brings together Europe’s leading life science organisations in managing and safeguarding the increasing volume of data being generated by publicly funded research. It coordinates, integrates and sustains bioinformatics resources across European countries and enables users in academia and industry to access services that are vital for their research. ELIXIR makes it easier for scientists to find and share data, exchange expertise, and agree on best practices and will help them gain new insights into how living organisms work. Ultimately, ELIXIR helps address the Grand Challenges across life sciences, from marine research – via plants and agriculture – to health research and medical sciences.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/elixir/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','fe19b663154e5cb6c8984641a1cd543d6f1d482f2dfcb66545e31f06d128a597','ff33bed4cfa7fc3aec79741b0c468da83f9cea033163960847d3985b71335835',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/elixir/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
