INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9D61A4562FB82C1CE7E0','research_infrastructure',NULL,'ERINHA | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/erinha/',NULL,'Health & Food / Landmark ERINHA European Research Infrastructure on Highly Pathogenic Agents',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:11.511Z','institutional_primary','en','The European Research Infrastructure on Highly Pathogenic Agents (ERINHA) is a distributed Research Infrastructure dedicated to develop an adequate and coordinated effort to address the challenges posed by the emergence or re-emergence of highly dangerous human and animal micro-organisms infecting humans. ERINHA seeks to reinforce the European capacities for the study of Risk Group 4 pathogens, enhance the coordination of Biosafety Level 4 (BSL-4) activities and give access to BSL-4 and complementary facilities (e.g. BSL-3) with longstanding experience of research in the field of highly infectious diseases. Such a coordinated approach is vital in a context marked by frequent globalization of infectious diseases with high risk for public health, society and economy, as suggested by the COVID-19 pandemic.','The European Research Infrastructure on Highly Pathogenic Agents (ERINHA) is a distributed Research Infrastructure dedicated to develop an adequate and coordinated effort to address the challenges posed by the emergence or re-emergence of highly dangerous human and animal micro-organisms infecting humans. ERINHA seeks to reinforce the European capacities for the study of Risk Group 4 pathogens, enhance the coordination of Biosafety Level 4 (BSL-4) activities and give access to BSL-4 and complementary facilities (e.g. BSL-3) with longstanding experience of research in the field of highly infectious diseases. Such a coordinated approach is vital in a context marked by frequent globalization of infectious diseases with high risk for public health, society and economy, as suggested by the COVID-19 pandemic.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/erinha/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','18ed0438050d1cd4f297781efb9f743b7722bbb4e1a290edd9351391e24d661e','9d61a4562fb82c1ce7e0f730bfb75709392d116911fd560b254a85e25112ddb9',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/erinha/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
