INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-43ACDE849DA342EE72D4','research_infrastructure',NULL,'EU-OPENSCREEN ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eu-openscreen-eric/',NULL,'Health & Food / Landmark EU-OPENSCREEN ERIC European Infrastructure of Open Screening Platforms for Chemical Biology',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:11.612Z','institutional_primary','en','The European Infrastructure of Open Screening Platforms for Chemical Biology (EU-OPENSCREEN) is a distributed Research Infrastructure that develops novel small chemical compounds which elicit specific biological responses on organisms, cells or cellular components. EU-OPENSCREEN enables scientists to use compound screening methods to validate novel therapeutic targets and support basic mechanistic studies addressing fundamental questions in cellular physiology, across domain systems, using the methods of chemical biology. EUOPENSCREEN is a cost-effective solution to address the need of the broad scientific community providing access to Europe’s leading screening platforms and chemistry groups, a jointly used compound collection and operating an open-access database accessible on a global basis.','The European Infrastructure of Open Screening Platforms for Chemical Biology (EU-OPENSCREEN) is a distributed Research Infrastructure that develops novel small chemical compounds which elicit specific biological responses on organisms, cells or cellular components. EU-OPENSCREEN enables scientists to use compound screening methods to validate novel therapeutic targets and support basic mechanistic studies addressing fundamental questions in cellular physiology, across domain systems, using the methods of chemical biology. EUOPENSCREEN is a cost-effective solution to address the need of the broad scientific community providing access to Europe’s leading screening platforms and chemistry groups, a jointly used compound collection and operating an open-access database accessible on a global basis.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eu-openscreen-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','2e94b31771010f5dfe63ca888bddf94b6ca26d0133866faf12b666e8dfe966cd','43acde849da342ee72d4daf114e7f95cf0a7bb1a7c310a47e6c95a073fb8db89',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eu-openscreen-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
