INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A1EB8AB7D569AD7CEC02','research_infrastructure',NULL,'Euro-BioImaging ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/euro-bioimaging-eric/',NULL,'Health & Food / Landmark Euro-BioImaging ERIC European Research Infrastructure for Imaging Technologies in Biological and Biomedical Sciences',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:12.091Z','institutional_primary','en','The European Research Infrastructure for Imaging Technologies in Biological and Biomedical Sciences (Euro-BioImaging, EuBI) is a distributed Research Infrastructure that provides a large-scale open physical access to state-of-the-art imaging technologies for life scientists in Europe and beyond. Euro-BioImaging will offer access to imaging instruments, expertise, training and data management services to infrastructure users and providers, both from academia and industry, and continuously evaluate and include new imaging technologies to ensure sustainable cuttingedge services. All scientists, regardless of their affiliation, area of expertise or field of activity can benefit from these pan-European open access services, which are provided with high-quality standards by leading imaging facilities.','The European Research Infrastructure for Imaging Technologies in Biological and Biomedical Sciences (Euro-BioImaging, EuBI) is a distributed Research Infrastructure that provides a large-scale open physical access to state-of-the-art imaging technologies for life scientists in Europe and beyond. Euro-BioImaging will offer access to imaging instruments, expertise, training and data management services to infrastructure users and providers, both from academia and industry, and continuously evaluate and include new imaging technologies to ensure sustainable cuttingedge services. All scientists, regardless of their affiliation, area of expertise or field of activity can benefit from these pan-European open access services, which are provided with high-quality standards by leading imaging facilities.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/euro-bioimaging-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','dd39b33e98c8a6c5b34442bf2c2f8bc9ccc12f40ea3afef6e0854b427424a937','a1eb8ab7d569ad7cec02895b3c8f1f407294fd79de29538392e53fd26ede522a',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/euro-bioimaging-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
