INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-5EFB1DA6597A33C92DEE','research_infrastructure',NULL,'INFRAFRONTIER | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/infrafrontier/',NULL,'Health & Food / Landmark INFRAFRONTIER European Research Infrastructure for the generation, phenotyping, archiving and distribution of mouse disease models',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:19.714Z','institutional_primary','en','The European Research Infrastructure for the generation, phenotyping, archiving and distribution of mouse disease models (INFRAFRONTIER) aims to build a distributed world-class Research Infrastructure that provides the biomedical research community with the tools needed to unravel the role of gene function in human health and disease. By offering access to a unique collection of mouse models and research tools and associated data, and to state-of-the-art technologies for mouse model development and phenotype analyses, INFRAFRONTIER enhances medical research and promotes studies that lead to breakthrough discoveries in cancer, metabolic and cardiovascular diseases, lung diseases, infectious diseases and the group of rare diseases, global threats to our socio-economic well-being.','The European Research Infrastructure for the generation, phenotyping, archiving and distribution of mouse disease models (INFRAFRONTIER) aims to build a distributed world-class Research Infrastructure that provides the biomedical research community with the tools needed to unravel the role of gene function in human health and disease. By offering access to a unique collection of mouse models and research tools and associated data, and to state-of-the-art technologies for mouse model development and phenotype analyses, INFRAFRONTIER enhances medical research and promotes studies that lead to breakthrough discoveries in cancer, metabolic and cardiovascular diseases, lung diseases, infectious diseases and the group of rare diseases, global threats to our socio-economic well-being.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/infrafrontier/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','52839dcc2e25925dae90878606f8125df095dd1763a80c2721127b48b9be630d','5efb1da6597a33c92dee54a227cb90317fedb5f2b877f76f282303198eca7a58',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/infrafrontier/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
