INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6D6767E845A741B59FB4','research_infrastructure',NULL,'INSTRUCT ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/instruct-eric/',NULL,'Health & Food / Landmark INSTRUCT ERIC Integrated Structural Biology Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:20.013Z','institutional_primary','en','The Integrated Structural Biology Infrastructure (INSTRUCT) is a distributed Research Infrastructure that provides peer-reviewed access to a broad palette of high-end technologies and methods, expertise and training in structural biology. INSTRUCT major goal is underpinning fundamental research and promoting innovation in the biological and medical sciences by providing an integrated approach that combines multiple technologies. INSTRUCT is a major player in delivering this strategy by creating close cooperation with other biological and medical sciences Research Infrastructures and establishing international partnership both with academia and industry supporting the biotechnology and pharmaceutical industries, and helping to tackle the Grand Challenges as defined by Horizon Europe.','The Integrated Structural Biology Infrastructure (INSTRUCT) is a distributed Research Infrastructure that provides peer-reviewed access to a broad palette of high-end technologies and methods, expertise and training in structural biology. INSTRUCT major goal is underpinning fundamental research and promoting innovation in the biological and medical sciences by providing an integrated approach that combines multiple technologies. INSTRUCT is a major player in delivering this strategy by creating close cooperation with other biological and medical sciences Research Infrastructures and establishing international partnership both with academia and industry supporting the biotechnology and pharmaceutical industries, and helping to tackle the Grand Challenges as defined by Horizon Europe.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/instruct-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','77abe72d1fe16438536ce9d8949953503fca536589498c28b94643046a007a34','6d6767e845a741b59fb436b1a19e0fdd867d0b94d32a37da385230fcd54781c0',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/instruct-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
