INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C4D9228D1638AC721A08','research_infrastructure',NULL,'MIRRI | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/mirri/',NULL,'Health & Food / Landmark MIRRI Microbial Resource Research Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:18.860Z','institutional_primary','en','The Microbial Resource Research Infrastructure (MIRRI) is a distributed Research Infrastructure for the preservation, systematic investigation, provision and valorisation of microbial resources and biodiversity. MIRRI aims to serve the Bioscience and the Bioindustry user communities by facilitating their access to a broad range of high-quality microbial bioresourses, microorganisms, their derivatives, associated data and services, with a special focus on the interconnection domains of Health & Food, Agro-Food, and Environment & Energy. The MIRRI partners strive to alleviate the fragmentation of bioresource holdings and expertise, to deliver fit-for-purpose microbial material, to add value to microbial diversity, and to discover and preserve the yet unknown or uncultivated microorganisms.','The Microbial Resource Research Infrastructure (MIRRI) is a distributed Research Infrastructure for the preservation, systematic investigation, provision and valorisation of microbial resources and biodiversity. MIRRI aims to serve the Bioscience and the Bioindustry user communities by facilitating their access to a broad range of high-quality microbial bioresourses, microorganisms, their derivatives, associated data and services, with a special focus on the interconnection domains of Health & Food, Agro-Food, and Environment & Energy. The MIRRI partners strive to alleviate the fragmentation of bioresource holdings and expertise, to deliver fit-for-purpose microbial material, to add value to microbial diversity, and to discover and preserve the yet unknown or uncultivated microorganisms.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/mirri/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e189c19f1e8bdb69ce80590dfd90d0181979e736119f38d163f06fd38e40f8a5','c4d9228d1638ac721a08694324dbc90022f815e6084b0e2f0fa1ba33e6639d38',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/mirri/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
