INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-CFEFC5F62B30BFEF4FFF','research_infrastructure',NULL,'EIRENE RI | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eirene-ri/',NULL,'Health & Food / Project EIRENE RI Research Infrastructure for EnvIRonmental Exposure assessmeNt in Europe',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:19.711Z','institutional_primary','en','The Research Infrastructure for EnvIRonmental Exposure assessmeNt in Europe (EIRENE RI) pioneers the first European Research Infrastructure on environmental determinants of human health, the Human Exposome. EIRENE RI intends to support large-scale research for the interdisciplinary assessment of environmental determinants of health, including indoor and outdoor environment factors, lifestyle, socioeconomics, and the individual’s ability to cope with various stressors such as infection or disease. EIRENE RI will provide harmonised workflows and integrated services for data and sample collection, as well as knowledge and tools that will be made accessible to academic researchers, private companies, public authorities and citizens through the EIRENE open-access system and the EIRENE knowledge hub.','The Research Infrastructure for EnvIRonmental Exposure assessmeNt in Europe (EIRENE RI) pioneers the first European Research Infrastructure on environmental determinants of human health, the Human Exposome. EIRENE RI intends to support large-scale research for the interdisciplinary assessment of environmental determinants of health, including indoor and outdoor environment factors, lifestyle, socioeconomics, and the individual’s ability to cope with various stressors such as infection or disease. EIRENE RI will provide harmonised workflows and integrated services for data and sample collection, as well as knowledge and tools that will be made accessible to academic researchers, private companies, public authorities and citizens through the EIRENE open-access system and the EIRENE knowledge hub.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eirene-ri/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c57684d5169467de979957d4c8fdecb51b16970503b4209978834fc0e9a09510','cfefc5f62b30bfef4fff035689a11ac75286d2e36f515c59653670e508410f2e',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eirene-ri/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
