INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A232EA39AC74F2F07B75','research_infrastructure',NULL,'EMPHASIS | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/emphasis/',NULL,'Health & Food / Project EMPHASIS European Infrastructure for Multi-scale Plant Phenomics and Simulation',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:36.344Z','institutional_primary','en','The European Infrastructure for Multi-scale Plant Phenomics and Simulation (EMPHASIS) is a distributed Research Infrastructure with the aim to develop and provide access to facilities and services addressing multi-scale plant phenotyping in different agro-climatic scenarios. It will establish an integrated European phenotyping infrastructure to analyse genotype performance under diverse environmental conditions and quantify the diversity of traits contributing to performance in diverse environmental conditions − plant architecture, major physiological functions and output, yield components and quality. EMPHASIS addresses the technological and organizational limits of European phenotyping, for a full exploitation of genetic and genomic resources available for crop improvement in changing climate.','The European Infrastructure for Multi-scale Plant Phenomics and Simulation (EMPHASIS) is a distributed Research Infrastructure with the aim to develop and provide access to facilities and services addressing multi-scale plant phenotyping in different agro-climatic scenarios. It will establish an integrated European phenotyping infrastructure to analyse genotype performance under diverse environmental conditions and quantify the diversity of traits contributing to performance in diverse environmental conditions − plant architecture, major physiological functions and output, yield components and quality. EMPHASIS addresses the technological and organizational limits of European phenotyping, for a full exploitation of genetic and genomic resources available for crop improvement in changing climate.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/emphasis/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','dccde04dcb40be1a1a4f5f9a74e46ae908d6f593d3439a48672928e43e43d3fb','a232ea39ac74f2f07b756d80c396914975c92962bf5361e1158bf4b396404384',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/emphasis/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'emphasis esfri roadmap 2021 the european infrastructure for multi-scale plant phenomics and simulation emphasis is a distributed research infrastructure with the aim to develop and provide access to facilities and services addressing multi-scale plant phenotyping in different agro-climatic scenarios. it will establish an integrated european phenotyping infrastructure to analyse genotype performance under diverse environmental conditions and quantify the diversity of traits contributing to performance in diverse environmental conditions plant architecture major physiological functions and output yield components and quality. emphasis addresses the technological and organizational limits of european phenotyping for a full exploitation of genetic and genomic resources available for crop improvement in changing climate. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='a232ea39ac74f2f07b756d80c396914975c92962bf5361e1158bf4b396404384' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-8CD069EE3FEDFD1E523C','research_infrastructure',NULL,'EU-IBISBA | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eu-ibisba/',NULL,'Health & Food / Project EU-IBISBA European Industrial Biotechnology Innovation and Synthetic Biology Accelerator',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:35.914Z','institutional_primary','en','The European Industrial Biotechnology Innovation and Synthetic Biology Accelerator (EU-IBISBA) is a distributed RI that provides translational Research & Development & Innovation services to an international community of industrial biotechnology stakeholders, including academia, SMEs and industry. EU-IBISBA contributes to the growth of biotechnology, providing academics and industry with a unique opportunity to access services and expertise necessary to move early-stage research results towards higher maturity and innovation. It delivers services at the exit point of basic and early stage applied research, and provides support for concept proofing, prototyping, upscaling and piloting, to bridge the innovation gap that separates academic research from industrial demonstration and premarket development.','The European Industrial Biotechnology Innovation and Synthetic Biology Accelerator (EU-IBISBA) is a distributed RI that provides translational Research & Development & Innovation services to an international community of industrial biotechnology stakeholders, including academia, SMEs and industry. EU-IBISBA contributes to the growth of biotechnology, providing academics and industry with a unique opportunity to access services and expertise necessary to move early-stage research results towards higher maturity and innovation. It delivers services at the exit point of basic and early stage applied research, and provides support for concept proofing, prototyping, upscaling and piloting, to bridge the innovation gap that separates academic research from industrial demonstration and premarket development.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eu-ibisba/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','9b1262b82bd3ec414cc30b00d7a52ed1e46faa0163d9f863bdc60ddbf7519428','8cd069ee3fedfd1e523c476d6cd0173159ce6bae1e2dbe9b4c0a78853007f173',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eu-ibisba/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'eu-ibisba esfri roadmap 2021 the european industrial biotechnology innovation and synthetic biology accelerator eu-ibisba is a distributed ri that provides translational research development innovation services to an international community of industrial biotechnology stakeholders including academia smes and industry. eu-ibisba contributes to the growth of biotechnology providing academics and industry with a unique opportunity to access services and expertise necessary to move early-stage research results towards higher maturity and innovation. it delivers services at the exit point of basic and early stage applied research and provides support for concept proofing prototyping upscaling and piloting to bridge the innovation gap that separates academic research from industrial demonstration and premarket development. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='8cd069ee3fedfd1e523c476d6cd0173159ce6bae1e2dbe9b4c0a78853007f173' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-CB2F686036F4446A8C96','research_infrastructure',NULL,'METROFOOD-RI | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/metrofood-ri/',NULL,'Health & Food / Project METROFOOD-RI Infrastructure for Promoting Metrology in Food and Nutrition',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:32:36.340Z','institutional_primary','en','The Infrastructure for promoting Metrology in Food and Nutrition (METROFOOD-RI) is a distributed Research Infrastructure to provide high-quality metrology services, knowledge and tools in food and nutrition. It comprises an important cross-section of highly interdisciplinary and interconnected fields throughout the food value chain, including agri-food, sustainable development, food safety, quality, traceability and authenticity, environmental safety and human health. METROFOOD-RI consists of a physical infrastructure (P-RI) and an electronic infrastructure (e-RI) to coordinate and integrate existing networks of plants, laboratories, experimental fields/farms for crop production/animal breeding, small-scale plants for food processing and storage, kitchen-labs for food preparation.','The Infrastructure for promoting Metrology in Food and Nutrition (METROFOOD-RI) is a distributed Research Infrastructure to provide high-quality metrology services, knowledge and tools in food and nutrition. It comprises an important cross-section of highly interdisciplinary and interconnected fields throughout the food value chain, including agri-food, sustainable development, food safety, quality, traceability and authenticity, environmental safety and human health. METROFOOD-RI consists of a physical infrastructure (P-RI) and an electronic infrastructure (e-RI) to coordinate and integrate existing networks of plants, laboratories, experimental fields/farms for crop production/animal breeding, small-scale plants for food processing and storage, kitchen-labs for food preparation.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/metrofood-ri/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','069667c9e8987416e01b4e2bc59c99ad160e68b804e8f63cf57ecf5395d0a664','cb2f686036f4446a8c968a63131aa5e1c91fef7806eafe97a6f1db6a05fa11af',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/metrofood-ri/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
