INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-54C9D27850DA0194D170','research_infrastructure',NULL,'CTA | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/cta/',NULL,'Physical Sciences & Engineering / Landmark CTA Cherenkov Telescope Array',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:38:48.939Z','institutional_primary','en','The Cherenkov Telescope Array (CTA) is an Observatory for ground-based very high-energy gamma-ray astronomy. Building on the technology of current generation ground-based gammaray detectors, CTA will be ten times more sensitive and have unprecedented accuracy in its detection of high-energy gamma rays with more than 100 telescopes located in the northern and southern hemispheres. CTA will provide the first complete and detailed view of the Universe in this part of the radiation spectrum and will contribute towards a better understanding of astrophysical and cosmological processes, such as the origin of cosmic rays and their role in the Universe, the nature and variety of particle acceleration around black holes and the ultimate composition of matter and physics beyond the Standard Model.','The Cherenkov Telescope Array (CTA) is an Observatory for ground-based very high-energy gamma-ray astronomy. Building on the technology of current generation ground-based gammaray detectors, CTA will be ten times more sensitive and have unprecedented accuracy in its detection of high-energy gamma rays with more than 100 telescopes located in the northern and southern hemispheres. CTA will provide the first complete and detailed view of the Universe in this part of the radiation spectrum and will contribute towards a better understanding of astrophysical and cosmological processes, such as the origin of cosmic rays and their role in the Universe, the nature and variety of particle acceleration around black holes and the ultimate composition of matter and physics beyond the Standard Model.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/cta/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','d5dd81de87c5809ef390b78fb57d4285e72f947a40e223bef1832f825688b6b3','54c9d27850da0194d1709cbcbf393e68bfda9e41a393628c5c7f9f83e16b3ba4',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/cta/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
