INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-8CA63EFEE61A0509D85D','research_infrastructure',NULL,'ELI ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eli-eric/',NULL,'Physical Sciences & Engineering / Landmark ELI ERIC Extreme Light Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:01.600Z','institutional_primary','en','The Extreme Light Infrastructure (ELI) is the world’s largest and most advanced high-power laser Infrastructure and a global technology and innovation leader in high-power, high-intensity, and short-pulsed laser systems. The international user facility ELI accomodates some of the most intense lasers in the world. ELI’s lasers produce ultra-short pulses of high energy photons, electrons, protons, neutrons, muons and neutrinos in the (sub-) attosecond regimes on demand. In terms of research, ELI’s lasers enable a broad range of discovery possibilities from pioneering research in physics to applications and engineering. As the technology develops and spreads, ELI will become one of the more cost-effective means to conduct ‘big science’ in physics, biology, medicine and materials science.','The Extreme Light Infrastructure (ELI) is the world’s largest and most advanced high-power laser Infrastructure and a global technology and innovation leader in high-power, high-intensity, and short-pulsed laser systems. The international user facility ELI accomodates some of the most intense lasers in the world. ELI’s lasers produce ultra-short pulses of high energy photons, electrons, protons, neutrons, muons and neutrinos in the (sub-) attosecond regimes on demand. In terms of research, ELI’s lasers enable a broad range of discovery possibilities from pioneering research in physics to applications and engineering. As the technology develops and spreads, ELI will become one of the more cost-effective means to conduct ‘big science’ in physics, biology, medicine and materials science.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eli-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','087897d7ab1e18a9d364fb2b18107416e3efbc6fdc3b5c0081d576cd45ee305e','8ca63efee61a0509d85daa248b0f16367543df71f1d823900b65349d247fdd7b',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eli-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
