INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C8E2480A1105A0D0FEA0','research_infrastructure',NULL,'ELT | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/elt/',NULL,'Physical Sciences & Engineering / Landmark ELT Extremely Large Telescope',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:01.913Z','institutional_primary','en','The Extremely Large Telescope (ELT) is a revolutionary groundbased telescope that will have a 39-metre main mirror and will be the largest visible and infrared light telescope in the world: the world’s biggest eye on the sky. In addition to this unparalleled size, the ELT will be equipped with a lineup of cutting-edge instruments, designed to cover a wide range of scientific possibilities. The leap forwards with the ELT can lead to a paradigm shift in our perception of the Universe. The ELT will track Earth-like planets around other stars, and has the potential of becoming the first telescope to find evidence of life outside of our Solar System. It will also probe the furthest reaches of the cosmos, revealing the properties of the very earliest galaxies and the nature of the dark Universe.','The Extremely Large Telescope (ELT) is a revolutionary groundbased telescope that will have a 39-metre main mirror and will be the largest visible and infrared light telescope in the world: the world’s biggest eye on the sky. In addition to this unparalleled size, the ELT will be equipped with a lineup of cutting-edge instruments, designed to cover a wide range of scientific possibilities. The leap forwards with the ELT can lead to a paradigm shift in our perception of the Universe. The ELT will track Earth-like planets around other stars, and has the potential of becoming the first telescope to find evidence of life outside of our Solar System. It will also probe the furthest reaches of the cosmos, revealing the properties of the very earliest galaxies and the nature of the dark Universe.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/elt/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','d99739c45c82a2922a3f48c223bfea61569bf11d68c4bb248169b545234c9711','c8e2480a1105a0d0fea02ebaee24684ecfd36de8a0d8351ffd14c727162a834b',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/elt/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
