INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F90B261961ECF0011A0A','research_infrastructure',NULL,'EMFL | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/emfl/',NULL,'Physical Sciences & Engineering / Landmark EMFL European Magnetic Field Laboratory',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:01.150Z','institutional_primary','en','The European Magnetic Field Laboratory (EMFL) develops and operates the highest possible magnetic field facilities and make them available to the scientific community for the systematic investigations and manipulation of material properties. The main research activities supported by EMFL are: magnetic and superconducting materials, strongly correlated electron systems, low dimensional magnetic materials, nanostructured materials, magnet design and technology, semiconductors and nanosystems, mesoscopic physic, strongly correlated electron systems, molecular magnetism, soft condensed matter. Very commonly, materials research provides the basis for innovation that help boost the economy while offering clean technology solutions to problems we are finding ourselves faced with in today’s world.','The European Magnetic Field Laboratory (EMFL) develops and operates the highest possible magnetic field facilities and make them available to the scientific community for the systematic investigations and manipulation of material properties. The main research activities supported by EMFL are: magnetic and superconducting materials, strongly correlated electron systems, low dimensional magnetic materials, nanostructured materials, magnet design and technology, semiconductors and nanosystems, mesoscopic physic, strongly correlated electron systems, molecular magnetism, soft condensed matter. Very commonly, materials research provides the basis for innovation that help boost the economy while offering clean technology solutions to problems we are finding ourselves faced with in today’s world.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/emfl/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e3016ffa8ba01f6da53c1feb04ccf2e874a663f1889e012cf50f8c147d6756ce','f90b261961ecf0011a0a91c37ec0677efce3827222966c193371cfd2f572302c',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/emfl/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
