INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-44C95BEF3BA8063417DE','research_infrastructure',NULL,'ESRF EBS | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/esrf-ebs/',NULL,'Physical Sciences & Engineering / Landmark ESRF EBS European Synchrotron Radiation Facility Extremely Brilliant Source',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:02.195Z','institutional_primary','en','The European Synchrotron Radiation Facility Extremely Brilliant Source (ESRF EBS) is the upgrade of the world-leading source of synchrotron X-rays and a centre of excellence for fundamental and innovation-driven research in condensed and living matter science. Operating more than 40 beamlines with state-of-the-art instrumentation, the ESRF serves ~10.000 scientists each year who study materials and living matter. With the Extremely Brilliant source (EBS), the world’s first fourth-generation of high-energy synchrotron, ESRF opens new vistas for X-ray science in imaging condensed and living matter from meter to nanometer scales, enabling scientists to address the global challenges facing our society such as health, climate changes and environment, but also energy and innovative industry.','The European Synchrotron Radiation Facility Extremely Brilliant Source (ESRF EBS) is the upgrade of the world-leading source of synchrotron X-rays and a centre of excellence for fundamental and innovation-driven research in condensed and living matter science. Operating more than 40 beamlines with state-of-the-art instrumentation, the ESRF serves ~10.000 scientists each year who study materials and living matter. With the Extremely Brilliant source (EBS), the world’s first fourth-generation of high-energy synchrotron, ESRF opens new vistas for X-ray science in imaging condensed and living matter from meter to nanometer scales, enabling scientists to address the global challenges facing our society such as health, climate changes and environment, but also energy and innovative industry.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/esrf-ebs/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','18e36b10751a7c227bdb139822bbec71db64e7e6d873aec1627c894a79b61aef','44c95bef3ba8063417de1b021c666d9eac13b0af080e15c166224e1b396fcdbc',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/esrf-ebs/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'esrf ebs esfri roadmap 2021 the european synchrotron radiation facility extremely brilliant source esrf ebs is the upgrade of the world-leading source of synchrotron x-rays and a centre of excellence for fundamental and innovation-driven research in condensed and living matter science. operating more than 40 beamlines with state-of-the-art instrumentation the esrf serves 10.000 scientists each year who study materials and living matter. with the extremely brilliant source ebs the world s first fourth-generation of high-energy synchrotron esrf opens new vistas for x-ray science in imaging condensed and living matter from meter to nanometer scales enabling scientists to address the global challenges facing our society such as health climate changes and environment but also energy and innovative industry. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='44c95bef3ba8063417de1b021c666d9eac13b0af080e15c166224e1b396fcdbc' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-7F3ACB857D92A89D6B5B','research_infrastructure',NULL,'European Spallation Source ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/european-spallation-source-eric/',NULL,'Physical Sciences & Engineering / Landmark European Spallation Source ERIC European Spallation Source',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:12.760Z','institutional_primary','en','The European Spallation Source (ESS) is a single-sited, multidisciplinary Research Infrastructure based on the world’s most powerful neutron source. The ESS will use nuclear spallation, a process in which neutrons are liberated from heavy elements by high energy protons, a much safer process than nuclear fission used by other operating facilities. The ESS will provide up to 100 times brighter neutron beams than currently available at existing facilities and thus empowering the study of the structure and function of matter from the microscopic down to the atomic scale. The ESS will enable scientific breakthroughs in research related to materials to improve and develop new solutions for health, environment, clean energy, and help addressing some of the most important societal challenges of our time.','The European Spallation Source (ESS) is a single-sited, multidisciplinary Research Infrastructure based on the world’s most powerful neutron source. The ESS will use nuclear spallation, a process in which neutrons are liberated from heavy elements by high energy protons, a much safer process than nuclear fission used by other operating facilities. The ESS will provide up to 100 times brighter neutron beams than currently available at existing facilities and thus empowering the study of the structure and function of matter from the microscopic down to the atomic scale. The ESS will enable scientific breakthroughs in research related to materials to improve and develop new solutions for health, environment, clean energy, and help addressing some of the most important societal challenges of our time.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/european-spallation-source-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','45e682ac9c1392620c0df1f609d966e62ec6b6ca9d33d7953873a4fca60f523d','7f3acb857d92a89d6b5b39b7d8e949ab405cb2137fb9f73f177c77c4a6b9393e',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/european-spallation-source-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
