INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-19C4109E6CD16B202085','research_infrastructure',NULL,'European XFEL | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/european-xfel/',NULL,'Physical Sciences & Engineering / Landmark European XFEL European X-Ray Free-Electron Laser Facility',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:11.612Z','institutional_primary','en','The European X-Ray Free-Electron Laser Facility (European XFEL) is a world leading Research Infrastructure for the generation of ultrashort X-ray flashes - 27,000 times per second and with a brilliance that is a billion times higher than that of the best conventional synchrotron X-ray radiation sources. The world’s largest X-ray laser creates all-new research opportunities for scientists and industrial users, pushing forward the frontiers of scientific knowledge and thus enabling us to solve major societal challenges. Using the X-ray flashes of the European XFEL, scientists are able to map the atomic details of viruses, decipher the molecular composition of cells, take three-dimensional images of the nanoworld, film chemical reactions, and study processes such as those occurring deep inside planets.','The European X-Ray Free-Electron Laser Facility (European XFEL) is a world leading Research Infrastructure for the generation of ultrashort X-ray flashes - 27,000 times per second and with a brilliance that is a billion times higher than that of the best conventional synchrotron X-ray radiation sources. The world’s largest X-ray laser creates all-new research opportunities for scientists and industrial users, pushing forward the frontiers of scientific knowledge and thus enabling us to solve major societal challenges. Using the X-ray flashes of the European XFEL, scientists are able to map the atomic details of viruses, decipher the molecular composition of cells, take three-dimensional images of the nanoworld, film chemical reactions, and study processes such as those occurring deep inside planets.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/european-xfel/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a13b341cb37869edb455ea5156f1aa2a9f5e4c712e08601faeec4992cbd44449','19c4109e6cd16b2020858da74b842a63f9287db6335fa6dea8326e0d84056b5e',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/european-xfel/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
