INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-3CD497F6E36D7E645F57','research_infrastructure',NULL,'FAIR | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/fair/',NULL,'Physical Sciences & Engineering / Landmark FAIR Facility for Antiproton and Ion Research',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:12.042Z','institutional_primary','en','The Facility for Antiproton and Ion Research (FAIR) is a new complex accelerator providing high-energy, high-intensity primary and secondary beams of antiprotons and ions to enable forefront research into the structure and dynamics of matter under extreme conditions. In close cooperation with astronomers, who use telescopes to view the Universe at a distance, the scientists at FAIR will directly create and examine cosmic matter in the laboratory, thereby providing new insights into the evolution of the Universe and the nucleosynthesis in stars and star explosions. In addition to the fundamental science research, FAIR is focusing on applications like radiobiological risk assessments for manned space missions, material sciences, plasma physics studies, and radiotherapy research.','The Facility for Antiproton and Ion Research (FAIR) is a new complex accelerator providing high-energy, high-intensity primary and secondary beams of antiprotons and ions to enable forefront research into the structure and dynamics of matter under extreme conditions. In close cooperation with astronomers, who use telescopes to view the Universe at a distance, the scientists at FAIR will directly create and examine cosmic matter in the laboratory, thereby providing new insights into the evolution of the Universe and the nucleosynthesis in stars and star explosions. In addition to the fundamental science research, FAIR is focusing on applications like radiobiological risk assessments for manned space missions, material sciences, plasma physics studies, and radiotherapy research.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/fair/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b672cc7e395eacd0c4a337e9dce16df87275f3dffda81219f4c2c4aa7d5f9f7b','3cd497f6e36d7e645f57592ae12acfbcf0e9a2a325fdf07eb4e886e9c1327441',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/fair/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
