INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-47DFB6AC69A657EC2823','research_infrastructure',NULL,'HL-LHC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/hl-lhc/',NULL,'Physical Sciences & Engineering / Landmark HL-LHC High-Luminosity Large Hadron Collider',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:12.396Z','institutional_primary','en','The High-Luminosity Large Hadron Collider (HL-LHC) is an upgrade of the LHC which aims to achieve instantaneous luminosities a factor of five larger than the LHC nominal value, thereby enabling the experiments to enlarge their data sample by one order of magnitude compared with the LHC baseline programme. Following five years of design study and R&D, this project will require about ten years of developments, prototyping, testing and implementation with operation expected to start in the second half of this decade. The timeline is dictated by many critical components of the accelerator ending their lifetime and need to be replaced. The upgrade phase is therefore crucial not only for the full exploitation of the LHC physics potential, but also to enable operation of the collider beyond 2027.','The High-Luminosity Large Hadron Collider (HL-LHC) is an upgrade of the LHC which aims to achieve instantaneous luminosities a factor of five larger than the LHC nominal value, thereby enabling the experiments to enlarge their data sample by one order of magnitude compared with the LHC baseline programme. Following five years of design study and R&D, this project will require about ten years of developments, prototyping, testing and implementation with operation expected to start in the second half of this decade. The timeline is dictated by many critical components of the accelerator ending their lifetime and need to be replaced. The upgrade phase is therefore crucial not only for the full exploitation of the LHC physics potential, but also to enable operation of the collider beyond 2027.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/hl-lhc/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','2d6676c380b449b9847b56377ef29f5206be88e947fa050921e486f5cf648f10','47dfb6ac69a657ec28232e557b18d23d93f642927c65b03e37c4c069b16cce52',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/hl-lhc/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
