INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F4228262954FAF1FDC46','research_infrastructure',NULL,'ILL | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ill/',NULL,'Physical Sciences & Engineering / Landmark ILL Institut Max von Laue - Paul Langevin',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:17.378Z','institutional_primary','en','The Institut Max von Laue - Paul Langevin (ILL) is the leading international research facility for neutron science and technology. The reactor provides intense beams of neutrons that enable a large and diverse scientific community of visiting academic and industrial researchers to make new scientific advances and discoveries. The ILL suite of high‐performance instruments is constantly developed and upgraded aiming at improving operation, adapting the instrumentation to new research environments and offering new innovative techniques. Research at the ILL addresses critical challenges across areas ranging from the study of the origin of the Universe to the understanding of viral diseases in living organisms. The ILL devotes a large part of its activity to new energies and the environment.','The Institut Max von Laue - Paul Langevin (ILL) is the leading international research facility for neutron science and technology. The reactor provides intense beams of neutrons that enable a large and diverse scientific community of visiting academic and industrial researchers to make new scientific advances and discoveries. The ILL suite of high‐performance instruments is constantly developed and upgraded aiming at improving operation, adapting the instrumentation to new research environments and offering new innovative techniques. Research at the ILL addresses critical challenges across areas ranging from the study of the origin of the Universe to the understanding of viral diseases in living organisms. The ILL devotes a large part of its activity to new energies and the environment.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ill/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b20e2b642adb82cae058549e5cc1796a4701f2f857d78b60a77967b53f030c17','f4228262954faf1fdc466f4d832389ea36ebe231b967c128f03c6593337e732b',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ill/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
