INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-CBE88FB808BC498F1D4E','research_infrastructure',NULL,'SKAO | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/skao/',NULL,'Physical Sciences & Engineering / Landmark SKAO Square Kilometre Array Observatory',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:16.800Z','institutional_primary','en','The Square Kilometre Array Observatory (SKAO) is a global effort to build and operate the largest and most sensitive radio telescope on Earth, with eventually over one million square metres of collecting area. SKAO will be able to look back into the furthest reaches of the cosmos to study the first structures in the Universe, as well as probing the nature of gravity and cosmic magnetism and exploring the origins of life itself. The scale of the SKA represents a huge leap forward in both engineering and research & development towards building and delivering a unique instrument, with the detailed design and preparation under way. As one of the largest scientific endeavours in history, the SKA will bring together a wealth of the world’s finest scientists, engineers and policy makers to bring the project to fruition.','The Square Kilometre Array Observatory (SKAO) is a global effort to build and operate the largest and most sensitive radio telescope on Earth, with eventually over one million square metres of collecting area. SKAO will be able to look back into the furthest reaches of the cosmos to study the first structures in the Universe, as well as probing the nature of gravity and cosmic magnetism and exploring the origins of life itself. The scale of the SKA represents a huge leap forward in both engineering and research & development towards building and delivering a unique instrument, with the detailed design and preparation under way. As one of the largest scientific endeavours in history, the SKA will bring together a wealth of the world’s finest scientists, engineers and policy makers to bring the project to fruition.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/skao/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','af4fbeceab9d182f9de4051734c6ed5448fa409e99b3fd32a383a791764d7ad0','cbe88fb808bc498f1d4e84efb4a2e3291c61c31d847c7803e097a1b5d04c2ea8',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/skao/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'skao esfri roadmap 2021 the square kilometre array observatory skao is a global effort to build and operate the largest and most sensitive radio telescope on earth with eventually over one million square metres of collecting area. skao will be able to look back into the furthest reaches of the cosmos to study the first structures in the universe as well as probing the nature of gravity and cosmic magnetism and exploring the origins of life itself. the scale of the ska represents a huge leap forward in both engineering and research development towards building and delivering a unique instrument with the detailed design and preparation under way. as one of the largest scientific endeavours in history the ska will bring together a wealth of the world s finest scientists engineers and policy makers to bring the project to fruition. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='cbe88fb808bc498f1d4e84efb4a2e3291c61c31d847c7803e097a1b5d04c2ea8' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-907271B27F9DB9437E21','research_infrastructure',NULL,'SPIRAL2 | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/spiral2/',NULL,'Physical Sciences & Engineering / Landmark SPIRAL2 Syst&#232;me de Production d’Ions Radioactifs en Ligne de 2e g&#233;n&#233;ration',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:16.555Z','institutional_primary','en','The Système de Production d’Ions Radioactifs en Ligne de 2e generation (SPIRAL2) is a linear particle accelerator facility to extend significantly the actual possibilities of Radioactive Ion Beam (RIB) to study fundamental nuclear physics and related applications. The impact of SPIRAL2 is enabling a scientific programme based on unique high-intensity beams of light, heavy-ions and neutrons well suited to address the most challenging nuclear and astrophysics questions aiming at the deeper understanding of the nature of atomic nucleus. SPIRAL2 will contribute to the physics of nuclear fission and fusion based on the collection of unprecedented detailed fundamental nuclear data, and to the production of rare radioisotopes for medicine, to radiobiology and to materials science.','The Système de Production d’Ions Radioactifs en Ligne de 2e generation (SPIRAL2) is a linear particle accelerator facility to extend significantly the actual possibilities of Radioactive Ion Beam (RIB) to study fundamental nuclear physics and related applications. The impact of SPIRAL2 is enabling a scientific programme based on unique high-intensity beams of light, heavy-ions and neutrons well suited to address the most challenging nuclear and astrophysics questions aiming at the deeper understanding of the nature of atomic nucleus. SPIRAL2 will contribute to the physics of nuclear fission and fusion based on the collection of unprecedented detailed fundamental nuclear data, and to the production of rare radioisotopes for medicine, to radiobiology and to materials science.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/spiral2/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','cec8246f02975cb04ef9f6a2f2b770b2dfc87ce1006f27ff5319afe40b7b9ffd','907271b27f9db9437e2134c7793e2ab205232119eaa0dc9d8661d44b01bcbe86',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/spiral2/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
