INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-3C2041B9E86704F0F2A5','research_infrastructure',NULL,'EST | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/est/',NULL,'Physical Sciences & Engineering / Project EST European Solar Telescope',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:16.938Z','institutional_primary','en','The European Solar Telescope (EST) is a 4-metre class telescope dedicated to study the fundamental processes in the Sun that control the solar atmosphere and its activity. EST will be optimised for high-resolution multi-wavelength simultaneous multiinstrument observations of the photosphere and chromosphere, as well as magnetic structures therein. One aim is to address the still unresolved and complex question concerning the emergence of magnetic fields at the solar surface and transfer of magnetic and kinetic energy from subsurface layers to the solar atmosphere. Understanding the interaction of plasmas with magnetic fields will also have many technological implications, for example in fusion nuclear reactors. Space missions are also tributary of data from ground solar telescopes.','The European Solar Telescope (EST) is a 4-metre class telescope dedicated to study the fundamental processes in the Sun that control the solar atmosphere and its activity. EST will be optimised for high-resolution multi-wavelength simultaneous multiinstrument observations of the photosphere and chromosphere, as well as magnetic structures therein. One aim is to address the still unresolved and complex question concerning the emergence of magnetic fields at the solar surface and transfer of magnetic and kinetic energy from subsurface layers to the solar atmosphere. Understanding the interaction of plasmas with magnetic fields will also have many technological implications, for example in fusion nuclear reactors. Space missions are also tributary of data from ground solar telescopes.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/est/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b5cfcd6a10387caa1e3a59a3b2db513fb505fa3857e3c1bd9336a896190224fb','3c2041b9e86704f0f2a5aea6cc1ba97ec0178594ba183cadccf4bfc4504f89a4',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/est/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
