INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-ABBDB311E3DCE3A4EA57','research_infrastructure',NULL,'ET | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/et/',NULL,'Physical Sciences & Engineering / Project ET Einstein Telescope',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:26.788Z','institutional_primary','en','The Einstein Telescope (ET) will be the European Third-Generation Gravitational Wave (3G GW) Observatory, a multi-detector, multiinterferometer designed to observe the whole Universe. Thanks to the unprecedented sensitivity of ET, Europe will take the lead in the newborn multi-messenger astronomy by combining information delivered by ET with optical, IR, UV, gamma, cosmic ray and neutrino telescopes observations. ET, being a unique tool to investigate the spacetime fabric of the Universe, will impact on our fundamental physics knowledge, and our understanding of the fundamental interactions governing the evolution of blackholes and neutron stars. The technologies needed for ET will affect industrial sectors, like lasers, sensors, optics, seismic isolation, and materials.','The Einstein Telescope (ET) will be the European Third-Generation Gravitational Wave (3G GW) Observatory, a multi-detector, multiinterferometer designed to observe the whole Universe. Thanks to the unprecedented sensitivity of ET, Europe will take the lead in the newborn multi-messenger astronomy by combining information delivered by ET with optical, IR, UV, gamma, cosmic ray and neutrino telescopes observations. ET, being a unique tool to investigate the spacetime fabric of the Universe, will impact on our fundamental physics knowledge, and our understanding of the fundamental interactions governing the evolution of blackholes and neutron stars. The technologies needed for ET will affect industrial sectors, like lasers, sensors, optics, seismic isolation, and materials.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/et/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','8723550c45ecd75555d9460b0222a1980f4845a69e5e620bbd3ea48986459eb6','abbdb311e3dce3a4ea57cf2d16703a31ab3d514ae8fdb4c98902bd32b22d2ee7',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/et/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
