INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-36847654740ED15E09A4','research_infrastructure',NULL,'EuPRAXIA | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eupraxia/',NULL,'Physical Sciences & Engineering / Project EuPRAXIA European Plasma Research Accelerator with Excellence in Applications',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:39:26.515Z','institutional_primary','en','The European Plasma Research Accelerator with Excellence in Applications (EuPRAXIA) is a distributed, compact and innovative accelerator facility based on plasma technology. By using plasma wakefields gradients as high as some tens of billions of electron volts per meter – as much as 1,000 times more – EuPRAXIA will be a transformative step in the development of ultracompact accelerators that could be used for a wide range of fundamental and applied research applications. It is the important intermediate step between proof-of-principle experiments and ground-breaking, ultra-compact accelerators for photon science, structural biology, particle physics detector development, materials science, medical imaging, radiation therapy, protons sources for hadron therapy and industrial applications.','The European Plasma Research Accelerator with Excellence in Applications (EuPRAXIA) is a distributed, compact and innovative accelerator facility based on plasma technology. By using plasma wakefields gradients as high as some tens of billions of electron volts per meter – as much as 1,000 times more – EuPRAXIA will be a transformative step in the development of ultracompact accelerators that could be used for a wide range of fundamental and applied research applications. It is the important intermediate step between proof-of-principle experiments and ground-breaking, ultra-compact accelerators for photon science, structural biology, particle physics detector development, materials science, medical imaging, radiation therapy, protons sources for hadron therapy and industrial applications.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eupraxia/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','23f7bb230f88d1663619c9c2cafc336d794ef9d35350f41de257b8150f7c7025','36847654740ed15e09a4350c56324afa7ea22d725c7a9cf746fbad99a1bd33f6',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eupraxia/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
