INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-BDAA0CCC7D1D534B94E5','research_infrastructure',NULL,'CESSDA ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/cessda-eric/',NULL,'Social & Cultural Innovation / Landmark CESSDA ERIC Consortium of European Social Science Data Archives',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:08.809Z','institutional_primary','en','The Consortium of European Social Science Data Archives (CESSDA) is a distributed Research Infrastructures serving as a large-scale, integrated and sustainable platform for data services relevant to the Social Sciences. It supports high-quality, national and international research and cooperation by bringing together Social Science data archives across Europe, and expand easy access to data and metadata regardless of borders. CESSDA is aiming at facilitating social, economic and political research, thus contributing to the production of effective solutions to the major challenges facing society today. CESSDA supports continuous learning and training of its data providers and user community to cover research data management, data discovery and reuse, digital preservation and data archiving.','The Consortium of European Social Science Data Archives (CESSDA) is a distributed Research Infrastructures serving as a large-scale, integrated and sustainable platform for data services relevant to the Social Sciences. It supports high-quality, national and international research and cooperation by bringing together Social Science data archives across Europe, and expand easy access to data and metadata regardless of borders. CESSDA is aiming at facilitating social, economic and political research, thus contributing to the production of effective solutions to the major challenges facing society today. CESSDA supports continuous learning and training of its data providers and user community to cover research data management, data discovery and reuse, digital preservation and data archiving.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/cessda-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','5785ae998f47a90f14736ae8ddb4773af4ebc7145f740f9f46e3532de321bf1a','bdaa0ccc7d1d534b94e545976d7ab651a5bfc4505ad69e464cd6bd0db0ed64e6',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/cessda-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'cessda eric esfri roadmap 2021 the consortium of european social science data archives cessda is a distributed research infrastructures serving as a large-scale integrated and sustainable platform for data services relevant to the social sciences. it supports high-quality national and international research and cooperation by bringing together social science data archives across europe and expand easy access to data and metadata regardless of borders. cessda is aiming at facilitating social economic and political research thus contributing to the production of effective solutions to the major challenges facing society today. cessda supports continuous learning and training of its data providers and user community to cover research data management data discovery and reuse digital preservation and data archiving. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='bdaa0ccc7d1d534b94e545976d7ab651a5bfc4505ad69e464cd6bd0db0ed64e6' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-66165965F330D4CE3C0E','research_infrastructure',NULL,'CLARIN ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/clarin-eric/',NULL,'Social & Cultural Innovation / Landmark CLARIN ERIC Common Language Resources and Technology Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:08.559Z','institutional_primary','en','The Common Language Resources and Technology Infrastructure (CLARIN) is a distributed Research Infrastructure that provides easy and sustainable access for scholars in the Humanities and Social Sciences to FAIR digital language data − in written, spoken or multimodal form − and advanced tools to discover, explore, exploit, annotate, analyse or combine them, independent of their location. CLARIN is building a networked federation of language data repositories, service centres and centres of expertise, with single sign-on access for all members of the academic community in all participating countries. Tools and data from different centres are interoperable, so that data collections can be combined and tools from different sources can be chained to perform complex operations to support researchers in their work.','The Common Language Resources and Technology Infrastructure (CLARIN) is a distributed Research Infrastructure that provides easy and sustainable access for scholars in the Humanities and Social Sciences to FAIR digital language data − in written, spoken or multimodal form − and advanced tools to discover, explore, exploit, annotate, analyse or combine them, independent of their location. CLARIN is building a networked federation of language data repositories, service centres and centres of expertise, with single sign-on access for all members of the academic community in all participating countries. Tools and data from different centres are interoperable, so that data collections can be combined and tools from different sources can be chained to perform complex operations to support researchers in their work.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/clarin-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','f0fc7cd7731ba1f021d9914e791a6389f61aacd6cfd67b387342a5b4c9b772bc','66165965f330d4ce3c0e36aad6411e20a07b42bdf77d5938580b0fcbd10e6b7c',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/clarin-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
