INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6EB68B7159F166424B11','research_infrastructure',NULL,'DARIAH ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/dariah-eric/',NULL,'Social & Cultural Innovation / Landmark DARIAH ERIC Digital Research Infrastructure for the Arts and Humanities',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:08.966Z','institutional_primary','en','The Digital Research Infrastructure for the Arts and Humanities (DARIAH) is a distributed Research Infrastructure to enhance and support digitally-enabled research and teaching for Arts and Humanities. DARIAH is a network of people, expertise, information, knowledge, content, methods, tools and technologies from its member countries. It develops, maintains and operates an Infrastructure that sustains researchers in building, analysing and interpreting digital resources. By working with communities of practice, DARIAH brings together state-of-the-art digital arts and humanities activities and scales their results to a European level. It preserves, provides access to and disseminates research that stems from these collaborations and ensures that best practices, methodological and technical standards are followed.','The Digital Research Infrastructure for the Arts and Humanities (DARIAH) is a distributed Research Infrastructure to enhance and support digitally-enabled research and teaching for Arts and Humanities. DARIAH is a network of people, expertise, information, knowledge, content, methods, tools and technologies from its member countries. It develops, maintains and operates an Infrastructure that sustains researchers in building, analysing and interpreting digital resources. By working with communities of practice, DARIAH brings together state-of-the-art digital arts and humanities activities and scales their results to a European level. It preserves, provides access to and disseminates research that stems from these collaborations and ensures that best practices, methodological and technical standards are followed.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/dariah-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','5f8f8981cd917712ce530d363deea4ef7011c5108430934b0df13b9a97682480','6eb68b7159f166424b11175797b37dd390afd370c2857f849d4d7f06ff631480',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/dariah-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
