INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-30BAEC8F616624954E0E','research_infrastructure',NULL,'ESS ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ess-eric/',NULL,'Social & Cultural Innovation / Landmark ESS ERIC European Social Survey',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:18.265Z','institutional_primary','en','The European Social Survey (ESS) is an academically driven crossnational survey that has been conducted across Europe since 2001. Every two years, face-to-face interviews are conducted with newly selected, cross-sectional samples. The ESS RI assembles, interprets and disseminates data on social attitudes and behaviours that are gathered in each of the participating countries. It responds to the academic, public policy and societal needs to understand social stability and change within the European context. The topics of the ESS include: citizen involvement and democracy, family and working life, personal and social wellbeing, attitudes to and experiences of ageism as well as trust in institutions. The survey allows for new topics to be introduced over time via an open academically-led competition.','The European Social Survey (ESS) is an academically driven crossnational survey that has been conducted across Europe since 2001. Every two years, face-to-face interviews are conducted with newly selected, cross-sectional samples. The ESS RI assembles, interprets and disseminates data on social attitudes and behaviours that are gathered in each of the participating countries. It responds to the academic, public policy and societal needs to understand social stability and change within the European context. The topics of the ESS include: citizen involvement and democracy, family and working life, personal and social wellbeing, attitudes to and experiences of ageism as well as trust in institutions. The survey allows for new topics to be introduced over time via an open academically-led competition.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ess-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e224aef2ea80514d358fb57abb614108619ebd931819e78d942d65ce1bb42747','30baec8f616624954e0ef34cf7ae8f557eb8c3a47c7f7f7a7f01492fcc1bba89',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ess-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
