INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-16C57518BD8615C189A1','research_infrastructure',NULL,'SHARE ERIC | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/share-eric/',NULL,'Social & Cultural Innovation / Landmark SHARE ERIC Survey of Health, Ageing and Retirement in Europe',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:18.260Z','institutional_primary','en','The Survey of Health, Ageing and Retirement in Europe (SHARE) is a Research Infrastructure for studying the effects of health, social, economic and environmental policies over the life-course of European citizens and beyond. From 2004 until today, 480,000 in-depth interviews with 140,000 people aged 50 or older from 28 European countries and Israel have been conducted. Thus, SHARE is the largest pan-European social science panel study providing internationally comparable longitudinal micro data which allows insights in the fields of public health and socio-economic living conditions of European individuals, both for scientists and policy makers. SHARE has global impact since it additionally is embedded in a network of sister studies all over the world, from the Americas to Eastern Asia.','The Survey of Health, Ageing and Retirement in Europe (SHARE) is a Research Infrastructure for studying the effects of health, social, economic and environmental policies over the life-course of European citizens and beyond. From 2004 until today, 480,000 in-depth interviews with 140,000 people aged 50 or older from 28 European countries and Israel have been conducted. Thus, SHARE is the largest pan-European social science panel study providing internationally comparable longitudinal micro data which allows insights in the fields of public health and socio-economic living conditions of European individuals, both for scientists and policy makers. SHARE has global impact since it additionally is embedded in a network of sister studies all over the world, from the Americas to Eastern Asia.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/share-eric/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','5035e54e389c7dc6e8d9794c6f3e755ca63163051db05c57b39f2bc545103466','16c57518bd8615c189a1604b32b8d3cefb931e4378ef2383f46ed55dec81b50e',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/share-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
