INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-00DE1323258BD1A503EB','research_infrastructure',NULL,'E-RIHS | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/e-rihs/',NULL,'Social & Cultural Innovation / Project E-RIHS European Research Infrastructure for Heritage Science',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:17.799Z','institutional_primary','en','The European Research Infrastructure for Heritage Science (E-RIHS) is a distributed Research Infrastructure to support research on heritage interpretation, preservation, documentation and management. E-RIHS will deliver integrated access to expertise, data and technologies through a standardized approach, and integrate world-leading European facilities into an organisation with a clear identity and a strong cohesive role within the global heritage science community. Through interdisciplinary access to the four platforms – E-RIHS ARCHLAB, E-RIHS DIGILAB, E-RIHS FIXLAB, E-RIHS MOLAB – E-RIHS supports a wide variety of research, from smaller object-focussed case studies to largescale and longer-term collaborative projects, and stimulates innovation in instrumentation, portable technologies and data science.','The European Research Infrastructure for Heritage Science (E-RIHS) is a distributed Research Infrastructure to support research on heritage interpretation, preservation, documentation and management. E-RIHS will deliver integrated access to expertise, data and technologies through a standardized approach, and integrate world-leading European facilities into an organisation with a clear identity and a strong cohesive role within the global heritage science community. Through interdisciplinary access to the four platforms – E-RIHS ARCHLAB, E-RIHS DIGILAB, E-RIHS FIXLAB, E-RIHS MOLAB – E-RIHS supports a wide variety of research, from smaller object-focussed case studies to largescale and longer-term collaborative projects, and stimulates innovation in instrumentation, portable technologies and data science.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/e-rihs/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','29af5eed587ebe63435b2426773bc46464553993c5ddb8d2ccaf517b0cbdc1e9','00de1323258bd1a503eb70a73d18a924d25bd6ffd25aa5e5865c27f9cea47f03',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/e-rihs/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
