INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-27EA19C8BC2DBB9569CA','research_infrastructure',NULL,'EHRI | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ehri/',NULL,'Social & Cultural Innovation / Project EHRI European Holocaust Research Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:18.270Z','institutional_primary','en','The European Holocaust Research Infrastructure (EHRI) is a pan-European distributed Research Infrastructure with the aim to support transnational Holocaust research, commemoration and education. EHRI provides access to information about dispersed sources, and develops tools and methods that enable researchers and archivists to collaboratively work to overcome one of the hallmark challenges of Holocaust research – the wide dispersal of sources across Europe and beyond, and the concomitant fragmentation of Holocaust historiography. Providing access – remotely by the EHRI Portal and physically by the access to the world’s twenty leading Holocaust archives – is vital for the innovation of Holocaust research and for the training of the next generation of Holocaust researchers and archivists.','The European Holocaust Research Infrastructure (EHRI) is a pan-European distributed Research Infrastructure with the aim to support transnational Holocaust research, commemoration and education. EHRI provides access to information about dispersed sources, and develops tools and methods that enable researchers and archivists to collaboratively work to overcome one of the hallmark challenges of Holocaust research – the wide dispersal of sources across Europe and beyond, and the concomitant fragmentation of Holocaust historiography. Providing access – remotely by the EHRI Portal and physically by the access to the world’s twenty leading Holocaust archives – is vital for the innovation of Holocaust research and for the training of the next generation of Holocaust researchers and archivists.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ehri/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ca16905d9e1614c3ee5fe1556525460bf9c0d4863b44d1b1f84b2fb7db40b744','27ea19c8bc2dbb9569caed5e2107f57a9b800dbdef78fe33e1bc175714650ba1',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ehri/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'ehri esfri roadmap 2021 the european holocaust research infrastructure ehri is a pan-european distributed research infrastructure with the aim to support transnational holocaust research commemoration and education. ehri provides access to information about dispersed sources and develops tools and methods that enable researchers and archivists to collaboratively work to overcome one of the hallmark challenges of holocaust research the wide dispersal of sources across europe and beyond and the concomitant fragmentation of holocaust historiography. providing access remotely by the ehri portal and physically by the access to the world s twenty leading holocaust archives is vital for the innovation of holocaust research and for the training of the next generation of holocaust researchers and archivists. research infrastructure',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='27ea19c8bc2dbb9569caed5e2107f57a9b800dbdef78fe33e1bc175714650ba1' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-30823965EB95475F31AF','research_infrastructure',NULL,'GGP | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ggp/',NULL,'Social & Cultural Innovation / Project GGP The Generations and Gender Programme',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:34.072Z','institutional_primary','en','The Generations and Gender Programme (GGP) is a distributed RI with the aim to provide scientists and policy makers with high quality and cross-nationally comparable longitudinal data on population and family dynamics to answer pressing scientific and societal challenges. The GGP is based on the collection, documentation, and dissemination of data from large-scale, nationally representative surveys in Europe and beyond. It provides data on transitions to adulthood, family dynamics, fertility decisions, work-life balance, well-being, and intergenerational exchanges. It maintains a Contextual Database which comprises a wide range of macro-level indicators characterizing the societal, economic and institutional context of countries to formulate empirically-informed policies on families and population.','The Generations and Gender Programme (GGP) is a distributed RI with the aim to provide scientists and policy makers with high quality and cross-nationally comparable longitudinal data on population and family dynamics to answer pressing scientific and societal challenges. The GGP is based on the collection, documentation, and dissemination of data from large-scale, nationally representative surveys in Europe and beyond. It provides data on transitions to adulthood, family dynamics, fertility decisions, work-life balance, well-being, and intergenerational exchanges. It maintains a Contextual Database which comprises a wide range of macro-level indicators characterizing the societal, economic and institutional context of countries to formulate empirically-informed policies on families and population.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ggp/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','6a9cdda179928ac08fc091396dfe023664f13d65ca42748b567f3303ac21c102','30823965eb95475f31af821c710d9d9c59ed052c69033340b05a1cfba35c24f8',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/ggp/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
