INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-BF2B3CA230064E4520C9','research_infrastructure',NULL,'GUIDE | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/guide/',NULL,'Social & Cultural Innovation / Project GUIDE Growing Up In Digital Europe: EuroCohort',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:33.258Z','institutional_primary','en','The Growing Up In Digital Europe: EuroCohort (GUIDE) will be Europe’s first comparative birth cohort survey, a Research Infrastructure that will be an important source of high quality longitudinal statistical evidence to support the development of social policies which will enhance the well-being of children, young people and their families across Europe. GUIDE/ EuroCohort will be an accelerated cohort survey including a sample of new born infants as well as a sample of school age children to be surveyed using a common questionnaire and data collection methodology at regular intervals until the age of 24 years. The data will be used by a broad community of researchers and will generate cross-culturally comparative results of potential great value to child and youth initiatives and policies.','The Growing Up In Digital Europe: EuroCohort (GUIDE) will be Europe’s first comparative birth cohort survey, a Research Infrastructure that will be an important source of high quality longitudinal statistical evidence to support the development of social policies which will enhance the well-being of children, young people and their families across Europe. GUIDE/ EuroCohort will be an accelerated cohort survey including a sample of new born infants as well as a sample of school age children to be surveyed using a common questionnaire and data collection methodology at regular intervals until the age of 24 years. The data will be used by a broad community of researchers and will generate cross-culturally comparative results of potential great value to child and youth initiatives and policies.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/guide/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','9eece9a1e758027f9c4bdb8b8cbfffc36815b34bf706a453c00e47d80ccb4272','bf2b3ca230064e4520c9af44894690b0dbe8635fe36ee9e08968ead63460b6a0',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/guide/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
