INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E894B7ACD3632B86879D','research_infrastructure',NULL,'OPERAS | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/operas/',NULL,'Social & Cultural Innovation / Project OPERAS OPen scholarly communication in the European Research Area for Social Sciences and Humanities',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:33.700Z','institutional_primary','en','The OPen scholarly communication in the European Research Area for Social Sciences and Humanities (OPERAS) is a distributed RI to enable Open Science and upgrade scholarly communication practices in the Social Sciences and Humanities in line with the EOSC. OPERAS pools resources and offers services to enable all SSH stakeholders to streamline their activities and maximize the societal impact, in an interdisciplinary, mission-driven approach. OPERAS fosters the co-creation and adoption of scholarly communication services addressing research needs in terms of discovery, content creation, quality assurance, dissemination, outreach, and evaluation of outputs. It catalyses knowledge and know-how sharing, practices adoption, and increases return on socio-economic investments.','The OPen scholarly communication in the European Research Area for Social Sciences and Humanities (OPERAS) is a distributed RI to enable Open Science and upgrade scholarly communication practices in the Social Sciences and Humanities in line with the EOSC. OPERAS pools resources and offers services to enable all SSH stakeholders to streamline their activities and maximize the societal impact, in an interdisciplinary, mission-driven approach. OPERAS fosters the co-creation and adoption of scholarly communication services addressing research needs in terms of discovery, content creation, quality assurance, dissemination, outreach, and evaluation of outputs. It catalyses knowledge and know-how sharing, practices adoption, and increases return on socio-economic investments.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/operas/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','1ad83e47995a7a106ac42f5e0faf20e050632a74d6fab0aebde947ef377db93a','e894b7acd3632b86879dd87bf9a0a2ada834e4ebddd2d02ced8beb710d4b1fa2',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/operas/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
