INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-1156E9B258C327847BF9','research_infrastructure',NULL,'RESILIENCE | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/resilience/',NULL,'Social & Cultural Innovation / Project RESILIENCE REligious Studies Infrastructure: tooLs, Innovation, Experts, conNections and Centres in Europe',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-05T19:40:33.614Z','institutional_primary','en','The REligious Studies Infrastructure: tooLs, Innovation, Experts, conNections and Centres in Europe (RESILIENCE) is a interdisciplinary Research Infrastructure for all Religious Studies, building a high-performance platform, supplying tools and services for scholars studying religions in their different forms and in their diachronic and synchronic variety. It responds to the need for the broader and more structured involvement of excellent researchers, producing productive skills, new knowledge, a new approach and a visible impact in terms of innovation in Religious Studies. RESILIENCE supplies easy access to digital and physical data on religion and to advanced tools in knowing and understanding these data, and thus facilitates high-quality research concerning religion all over Europe and beyond.','The REligious Studies Infrastructure: tooLs, Innovation, Experts, conNections and Centres in Europe (RESILIENCE) is a interdisciplinary Research Infrastructure for all Religious Studies, building a high-performance platform, supplying tools and services for scholars studying religions in their different forms and in their diachronic and synchronic variety. It responds to the need for the broader and more structured involvement of excellent researchers, producing productive skills, new knowledge, a new approach and a visible impact in terms of innovation in Religious Studies. RESILIENCE supplies easy access to digital and physical data on religion and to advanced tools in knowing and understanding these data, and thus facilitates high-quality research concerning religion all over Europe and beyond.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/resilience/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','ad319ad791a1e89061ae01aa320c979a4df496f1ebe906517ca3aa6cc04698b2','1156e9b258c327847bf9c0e3e7b5e496c9519ed65294e45f9ff239b0d0bd7306',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/resilience/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
