INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C64A45FB34D9C0216A47','public_higher_education_research',NULL,'Études | Projets de fin d&rsquo;études | Catégories |','https://paris-malaquais.archi.fr/etudes/gf/pfe/',NULL,'École nationale supérieure d''architecture de Paris-Malaquais',NULL,'France','Europe','public_higher_education_research_source',NULL,NULL,'2026-10-05T19:29:33.545Z','institutional_primary','fr','Tout au long des cycles licence et master, les étudiants en architecture explorent des solutions, inventent des formes, pensent des dispositifs architecturaux et des projets qui s’inscrivent dans la préoccupation première de l’amélioration de la vie quotidienne des usagers et dans la qualité des paysages urbains ou naturels. Ils développent l’art du bâtir et le savoir-faire de l’expérimentation constructive. Le projet de fin d’études (PFE) est pour eux l’ultime étape conduisant au diplôme d’État d’architecte (DEA) et leur projection possible dans le monde professionnel. Il constitue en ce sens une synthèse de leurs études et une vitrine des compétences acquises. Pour le parcours de préparation de leur PFE, les étudiants ont à choisir parmi l’un des départements pédagogiques de Malaquais, structuration qui constitue l’une des spécificités de notre école. &gt; Voir ici la mappemonde des PF','Tout au long des cycles licence et master, les étudiants en architecture explorent des solutions, inventent des formes, pensent des dispositifs architecturaux et des projets qui s’inscrivent dans la préoccupation première de l’amélioration de la vie quotidienne des usagers et dans la qualité des paysages urbains ou naturels. Ils développent l’art du bâtir et le savoir-faire de l’expérimentation constructive. Le projet de fin d’études (PFE) est pour eux l’ultime étape conduisant au diplôme d’État d’architecte (DEA) et leur projection possible dans le monde professionnel. Il constitue en ce sens une synthèse de leurs études et une vitrine des compétences acquises. Pour le parcours de préparation de leur PFE, les étudiants ont à choisir parmi l’un des départements pédagogiques de Malaquais, structuration qui constitue l’une des spécificités de notre école. &gt; Voir ici la mappemonde des PF',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://paris-malaquais.archi.fr/etudes/gf/pfe/',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','4109d672cd951a8ac6a5095ec601e62664380a6e285d1c349d51476b7f5f53d4','c64a45fb34d9c0216a47522696c11063b90eb13f7f39fcd5aefbc1c7fbf5a2bb',1,1,1,1 FROM sources WHERE root_url='https://paris-malaquais.archi.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
