INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-362840AE8A49150617EA','public_higher_education_research',NULL,'Inauguration de la reconstruction de deux laboratoires de recherche : le CIMAP et le GREYC - ENSICAEN','https://www.ensicaen.fr/inauguration-de-la-reconstruction-de-deux-laboratoires-de-recherche-le-cimap-et-le-greyc/',NULL,'École nationale supérieure d''ingénieurs de Caen','vanessa dubois','France','Europe','public_higher_education_research_source','2016-05-19T09:26:49+00:00',NULL,'2026-10-05T19:29:51.836Z','institutional_primary','fr','Jeudi 19 mai, Jean-François Hamet, Directeur Général de l&rsquo;ENSICAEN, accompagné de Joël Bruneau, Président de la Communauté d’agglomération Caen la mer, Hervé Morin, Président de la Région Normandie et Jean-Charles Quirion, Délégué Régional à la Recherche et à la Technologie de Normandie représentant Madame La Préfète de la Région Normandie, ont inauguré la phase 2 de l&rsquo;agrandissement de l&rsquo;ENSICAEN avec la reconstruction des laboratoires de recherche CIMAP et GREYC . Une phase 1, première extension réalisée en 2010 qui avait permis la création d’un nouveau bâtiment dédié à l’enseignement, l’ENSICAEN, poursuit son développement.','Jeudi 19 mai, Jean-François Hamet, Directeur Général de l&rsquo;ENSICAEN, accompagné de Joël Bruneau, Président de la Communauté d’agglomération Caen la mer, Hervé Morin, Président de la Région Normandie et Jean-Charles Quirion, Délégué Régional à la Recherche et à la Technologie de Normandie représentant Madame La Préfète de la Région Normandie, ont inauguré la phase 2 de l&rsquo;agrandissement de l&rsquo;ENSICAEN avec la reconstruction des laboratoires de recherche CIMAP et GREYC . Une phase 1, première extension réalisée en 2010 qui avait permis la création d’un nouveau bâtiment dédié à l’enseignement, l’ENSICAEN, poursuit son développement.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ensicaen.fr/inauguration-de-la-reconstruction-de-deux-laboratoires-de-recherche-le-cimap-et-le-greyc/',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','5a612803c1e1d87724bb22215c064ddb4b5efe8eff6851da2365993ee5ac9d1b','362840ae8a49150617ea9e0ca8242272b85a6d80f366e85eba475493d39e86b9',1,1,1,1 FROM sources WHERE root_url='https://www.ensicaen.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
