INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9C43496F6A7F4667DF53','public_higher_education_research',NULL,'ENSFEA &raquo; L’ENFA entre dans le 7ème programme-cadre pour la recherche et le développement technologique','https://www.ensfea.fr/2013/10/02/lenfa-entre-dans-le-7eme-programme-cadre-pour-la-recherche-et-le-developpement-technologique/',NULL,'École nationale supérieure de formation de l’enseignement agricole',NULL,'France','Europe','public_higher_education_research_source',NULL,NULL,'2026-10-05T19:29:49.198Z','institutional_primary','fr','Facebook LinkedIn Email L’ENFA entre dans le 7ème programme-cadre pour la recherche et le développement technologique Tags: CASSIS , PARRISE , umr EFTS &#8212; Le 2 octobre 2013 Dans Divers , Recherche Les enseignants chercheurs en didactique des Questions Socialement Vives (QSV) au sein de l’ équipe EFTS ont obtenu l’accord final concernant deux projets de recherche européens : CASSIS (Communication About SocioScientific Issues) et PARRISE (Promoting Attainment of Responsible Research and Innovation in Science Education). Ces travaux ambitieux qui s’étaleront sur un cycle de 4 ans (2014 – 2018), s’inscrivent dans le 7ème programme cadre de recherche et de développement technologique , financés par la Commission Européenne.','Facebook LinkedIn Email L’ENFA entre dans le 7ème programme-cadre pour la recherche et le développement technologique Tags: CASSIS , PARRISE , umr EFTS &#8212; Le 2 octobre 2013 Dans Divers , Recherche Les enseignants chercheurs en didactique des Questions Socialement Vives (QSV) au sein de l’ équipe EFTS ont obtenu l’accord final concernant deux projets de recherche européens : CASSIS (Communication About SocioScientific Issues) et PARRISE (Promoting Attainment of Responsible Research and Innovation in Science Education). Ces travaux ambitieux qui s’étaleront sur un cycle de 4 ans (2014 – 2018), s’inscrivent dans le 7ème programme cadre de recherche et de développement technologique , financés par la Commission Européenne.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ensfea.fr/2013/10/02/lenfa-entre-dans-le-7eme-programme-cadre-pour-la-recherche-et-le-developpement-technologique/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','0d2b60cf5a64ff7d97d1c214c93429e37dd4f5629cb87feda5608089a5ba9eac','9c43496f6a7f4667df53bdf51ffd3a6820969291bafa4663a31afd1ebec67fb4',1,1,1,1 FROM sources WHERE root_url='https://www.ensfea.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
