INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-22D5E77B8CEDA6B3970C','public_higher_education_research',NULL,'Programme de recherche DECRIPT (AMI-SHS) | Institut National des Langues et Civilisations Orientales','https://www.inalco.fr/decript',NULL,'Institut national des langues et civilisations orientales',NULL,'France','Europe','public_higher_education_research_source','2026-10-08/2026-10-08',NULL,'2026-10-05T19:33:11.149Z','institutional_primary','fr','DECRIPT est un programme pluridisciplinaire de recherche et de transfert vers la société et les politiques publiques, qui examine comment la mobilisation de récits civilisationnels interroge et remet en question les normes ou référents universels, s’insère au cœur des conflits contemporains et contribue à redéfinir les modèles de gouvernance multilatérale. Porté par l''Inalco, réunissant près de 400 chercheurs et praticiens appartenant aux 15 partenaires du consortium et plus de 40 institutions parties prenantes, DECRIPT associe les sciences humaines, les sciences sociales et l''analyse de données pour produire des recherches originales, empiriquement ancrées, permettant d’éclairer les décisions publiques autour de ces enjeux-clés. Grâce à son Lab’, DECRIPT met en relation chercheurs, décideurs et acteurs de la société civile pour développer des cadres analytiques et des outils originaux p','DECRIPT est un programme pluridisciplinaire de recherche et de transfert vers la société et les politiques publiques, qui examine comment la mobilisation de récits civilisationnels interroge et remet en question les normes ou référents universels, s’insère au cœur des conflits contemporains et contribue à redéfinir les modèles de gouvernance multilatérale. Porté par l''Inalco, réunissant près de 400 chercheurs et praticiens appartenant aux 15 partenaires du consortium et plus de 40 institutions parties prenantes, DECRIPT associe les sciences humaines, les sciences sociales et l''analyse de données pour produire des recherches originales, empiriquement ancrées, permettant d’éclairer les décisions publiques autour de ces enjeux-clés. Grâce à son Lab’, DECRIPT met en relation chercheurs, décideurs et acteurs de la société civile pour développer des cadres analytiques et des outils originaux p',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.inalco.fr/decript',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','7e0559d1ed193e263542da053affde9963ea6cf922f44a583792e97f82cec086','22d5e77b8ceda6b3970c14c8b7d87a3c160e3853e3bb7a74e552396aae788c71',1,1,1,1 FROM sources WHERE root_url='https://www.inalco.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
