INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F2B8264FA9EFC5848F68','public_higher_education_research',NULL,'Le Crédit Agricole d&#039;Ile-de-France Mécénat financera le renouvellement du matériel dédié au pôle imagerie 3D du laboratoire de Recherche | Institut national du patrimoine','https://www.inp.fr/actualites/credit-agricole-dile-france-mecenat-financera-renouvellement-materiel-dedie-au-pole-imagerie-3d-laboratoire-recherche',NULL,'Institut national du patrimoine',NULL,'France','Europe','public_higher_education_research_source','2023-06-09',NULL,'2026-10-05T19:33:38.912Z','institutional_primary','fr','Le Crédit Agricole d’Ile-de-France, à travers son fonds de dotation Crédit Agricole d’Ile-de-France Mécénat, inscrit son soutien à l&#039;Institut national du patrimoine (Inp) dans la durée avec une nouvelle convention signée le 8 juillet 2019. Cet engagement passe notamment par le financement de l’acquisition d’équipements scientifiques de pointe indispensables au maintien de l’excellence des enseignements dispensés aux élèves restaurateurs de l’Inp.','Le Crédit Agricole d’Ile-de-France, à travers son fonds de dotation Crédit Agricole d’Ile-de-France Mécénat, inscrit son soutien à l&#039;Institut national du patrimoine (Inp) dans la durée avec une nouvelle convention signée le 8 juillet 2019. Cet engagement passe notamment par le financement de l’acquisition d’équipements scientifiques de poin