INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-91B59094B3AC5C6244C7','public_higher_education_research',NULL,'Pop’Sciences Mag explore la matière avec des scientifiques de nos laboratoires - Lyon 1 Université Claude Bernard','https://www.univ-lyon1.fr/actualites/popsciences-mag-explore-la-matiere-avec-des-scientifiques-de-nos-laboratoires',NULL,'Lyon-I université',NULL,'France','Europe','public_higher_education_research_source',NULL,NULL,'2026-10-05T19:37:52.642Z','institutional_primary','fr','Pop’Sciences Mag consacre son nouveau numéro (n°16) à un thème fondamental et plus que jamais d’actualité : la matière. Qu’elle soit première, transformée, réemployée, consommée, rejetée ou recyclée, la matière traverse nos vies et révèle nos choix individuels comme collectifs. Cette édition propose d’en explorer les multiples visages à travers des enquêtes, des analyses, des témoignages et des reportages, pour mieux comprendre les enjeux environnementaux, économiques et sociaux qui lui sont liés. Deux scientifiques de l’Université Claude Bernard Lyon 1 y apportent leur expertise.','Pop’Sciences Mag consacre son nouveau numéro (n°16) à un thème fondamental et plus que jamais d’actualité : la matière. Qu’elle soit première, transformée, réemployée, consommée, rejetée ou recyclée, la matière traverse nos vies et révèle nos choix individuels comme collectifs. Cette édition propose d’en explorer les multiples visages à travers des enquêtes, des analyses, des témoignages et des reportages, pour mieux comprendre les enjeux environnementaux, économiques et sociaux qui lui sont liés. Deux scientifiques de l’Université Claude Bernard Lyon 1 y apportent leur expertise.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.univ-lyon1.fr/actualites/popsciences-mag-explore-la-matiere-avec-des-scientifiques-de-nos-laboratoires',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','8e6aa2b1adc35ad8e1ea86d25e7ea9d104fec30659c973a490b868dbbe0f79c9','91b59094b3ac5c6244c7c9ac9efb46f8dc3afed6f8571ced7dacb4231f176866',1,1,1,1 FROM sources WHERE root_url='https://www.univ-lyon1.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
