INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-D5058CA1BF7F48AF75C4','public_higher_education_research',NULL,'The Conversation : "L’Europe veut libérer le potentiel des données de santé" - Université Grenoble Alpes','https://www.univ-grenoble-alpes.fr/actualites/a-la-une/sciences-et-innovation/the-conversation/sante/the-conversation-l-europe-veut-liberer-le-potentiel-des-donnees-de-sante--1792562.kjsp',NULL,'Université Grenoble Alpes','Université Grenoble Alpes','France','Europe','public_higher_education_research_source',NULL,NULL,'2026-10-05T19:42:37.501Z','institutional_primary','fr','La souveraineté numérique est devenue un objectif central de la politique européenne. Au-delà de l’intelligence artificielle, des semi-conducteurs et du cloud computing, ou « informatique dématérialisée », le débat s’étend désormais à l’une des catégories d’information les plus sensibles détenues par les gouvernements : les données de santé, qui sont collectées par les hôpitaux, l’assurance-maladie, les laboratoires d’analyses médicales et les institutions publiques. Pour mieux anticiper les risques de santé publique, suivre les épidémies, allouer les ressources, l’Union européenne a adopté la création d’un Espace européen des données de santé, qui entrera en application de manière différée à partir de mars 2027 et qui soulève de nombreuses questions de gouvernance, bien au-delà de la protection de la vie privée.','La souveraineté numérique est devenue un objectif central de la politique européenne. Au-delà de l’intelligence artificielle, des semi-conducteurs et du cloud computing, ou « informatique dématérialisée », le débat s’étend désormais à l’une des catégories d’information les plus sensibles détenues par les gouvernements : les données de santé, qui sont collectées par les hôpitaux, l’assurance-maladie, les laboratoires d’analyses médicales et les institutions publiques. Pour mieux anticiper les risques de santé publique, suivre les épidémies, allouer les ressources, l’Union européenne a adopté la création d’un Espace européen des données de santé, qui entrera en application de manière différée à partir de mars 2027 et qui soulève de nombreuses questions de gouvernance, bien au-delà de la protection de la vie privée.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.univ-grenoble-alpes.fr/actualites/a-la-une/sciences-et-innovation/the-conversation/sante/the-conversation-l-europe-veut-liberer-le-potentiel-des-donnees-de-sante--1792562.kjsp',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','43a0cdc420c1ec8d76bcd0f0eaec2682b300bba630ba8ff9afa3bb90b26fed11','d5058ca1bf7f48af75c40bc674dabe03e594a4c607d6fe3bcc7a5a0b2ae8f9d6',1,1,1,1 FROM sources WHERE root_url='https://www.univ-grenoble-alpes.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
