INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-24DA13EF1676AA3C44A6','applied_research',NULL,'Research for the future - Fraunhofer IWU','https://www.iwu.fraunhofer.de/en.html',NULL,'Machine Tools and Forming Technology',NULL,'Germany','Europe','official_research_institution',NULL,NULL,'2026-10-05T19:37:56.523Z','institutional_primary','en','Fraunhofer IWU - your partner for research and development in production engineering The Fraunhofer Institute for Machine Tools and Forming Technology IWU is your innovation-driven partner for research and development in production engineering. Around 670 highly qualified employees work at our locations in Chemnitz, Cottbus, Dresden, Leipzig, Wolfsburg, and Zittau. We unlock potential for competitive manufacturing, across industries like automotive, aerospace, electrical engineering, and precision engineering. Our research and contract research encompass the entire manufacturing ecosystem, from individual components to processes, methods, complex machine systems and human interaction.','Fraunhofer IWU - your partner for research and development in production engineering The Fraunhofer Institute for Machine Tools and Forming Technology IWU is your innovation-driven partner for research and development in production engineering. Around 670 highly qualified employees work at our locations in Chemnitz, Cottbus, Dresden, Leipzig, Wolfsburg, and Zittau. We unlock potential for competitive manufacturing, across industries like automotive, aerospace, electrical engineering, and precision engineering. Our research and contract research encompass the entire manufacturing ecosystem, from individual components to processes, methods, complex machine systems and human interaction.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.iwu.fraunhofer.de/en.html',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c97ab73f38b1324cd171aa5523059476e4dd63853413ee764bc8952a71e4e468','24da13ef1676aa3c44a66240a26880224e69ce3bd8b60619cd25488cc0c5786a',1,1,1,1 FROM sources WHERE root_url='https://www.iwu.fraunhofer.de/en.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
