INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-80A900ABECFBFC491C0C','public_higher_education_research',NULL,'East Tennessee State University','https://www.etsu.edu/ehome/',NULL,'East Tennessee State University',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-05T19:33:10.966Z','institutional_primary','en','ETSU was founded in 1911 with a singular purpose: to improve the quality of life for people in the region and beyond. Today, the university offers more than 160 programs at the undergraduate, graduate, and professional levels and serves approximately 14,000 students each year at its main campus in Johnson City and off-campus instructional sites throughout the region. Through its world-class health sciences programs and integrated approach to healthcare education, the institution is a highly respected leader in rural health research and practices. ETSU also boasts nationally ranked and recognized programs in the arts, technology, and computing, and media studies. With more than 100,000 living alumni who call ETSU their alma mater, the impact of its students, alumni, faculty, and staff can be seen across the Appalachian Highlands and around the world!','ETSU was founded in 1911 with a singular purpose: to improve the quality of life for people in the region and beyond. Today, the university offers more than 160 programs at the undergraduate, graduate, and professional levels and serves approximately 14,000 students each year at its main campus in Johnson City and off-campus instructional sites throughout the region. Through its world-class health sciences programs and integrated approach to healthcare education, the institution is a highly respected leader in rural health research and practices. ETSU also boasts nationally ranked and recognized programs in the arts, technology, and computing, and media studies. With more than 100,000 living alumni who call ETSU their alma mater, the impact of its students, alumni, faculty, and staff can be seen across the Appalachian Highlands and around the world!',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.etsu.edu/ehome/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','0370fd44351f008fc9da746b8f3f693321700bed9e8132f06ed9d31fa6c03c29','80a900abecfbfc491c0c560fe100ed97e3bfcfb67f420b78cb9b83e344c03cbf',1,1,1,1 FROM sources WHERE root_url='https://www.etsu.edu/ehome/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
