INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C79C0245C68F1B23E149','research',NULL,'Ames Laboratory','https://www.ameslab.gov/',NULL,'Learn More',NULL,'United States','North America','official_research_institution',NULL,NULL,'2026-10-05T19:37:51.315Z','institutional_primary','en','Research teams in the Division of Chemical and Biological Sciences conduct fundamental and applied studies of how to control and manipulate chemicals and biological materials. We work to develop new catalysts that enable more efficient chemical reactions, discover new ways to convert plants to biofuels, understand how solvents affect chemical reactions, and how molecules diffuse on surfaces and through tiny pores.Developing new instruments is also at the heart of our research. Understanding Nature&#039;s fundamental building blocks requires us to be able to see things at tiny length scales and fast time scales. We are at the cutting edge of developing tools and methods for understanding what drives biological and chemical processes; we are leaders in the fields of mass spectrometric imaging, solid state NMR, Raman spectroscopy, and single particle analysis.Basic research conducted within','Research teams in the Division of Chemical and Biological Sciences conduct fundamental and applied studies of how to control and manipulate chemicals and biological materials. We work to develop new catalysts that enable more efficient chemical reactions, discover new ways to convert plants to biofuels, understand how solvents affect chemical reactions, and how molecules diffuse on surfaces and through tiny pores.Developing new instruments is also at the heart of our research. Understanding Nature&#039;s fundamental building blocks requires us to be able to see things at tiny length scales and fast time scales. We are at the cutting edge of developing tools and methods for understanding what drives biological and chemical processes; we are leaders in the fields of mass spectrometric imaging, solid state NMR, Raman spectroscopy, and single particle analysis.Basic research conducted within',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ameslab.gov/',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3c3f311f25290c0560741142ad94e3116f5f9a7b2935283acee2b50e2ec466f9','c79c0245c68f1b23e149ba43f1237c9cbc39ac3201eed96baf2199df0384dc86',1,1,1,1 FROM sources WHERE root_url='https://www.ameslab.gov/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
