INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-8718181E845A4E4B5A76','public_higher_education_research',NULL,'Technology Accessibility Services - Lincoln University','https://www.lincoln.edu/office-institutional-equity/accessibility-services-program/technology-accessibility-services.html',NULL,'Lincoln University',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-05T19:38:27.097Z','institutional_primary','en','I. Purpose Lincoln University (&#8220;LU&#8221;) is committed to providing accessibility through all its Information Technology efforts. This document provides guide to the University units and individuals employed by the University to fulfill LU&#8217;s commitment to equal and equitable access to information technology. Following these standards will ensure that people with disabilities have access to the same services and content that are available to people without disabilities, including services and content made available through the use of information technology. Information Technology procured, developed, and maintained, and used by the LU community should provide substantially similar functionality, experience, and information access to individuals with disabilities as it provides to others.','I. Purpose Lincoln University (&#8220;LU&#8221;) is committed to providing accessibility through all its Information Technology efforts. 