INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-0A239596DC4AEA4A8CAC','public_higher_education_research',NULL,'Construction Engineering Technology (BSCT)','https://www.latech.edu/academics/degrees-programs/engineering-science/construction-engineering-technology-bsct.php',NULL,'Louisiana Tech University',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-05T19:38:38.443Z','institutional_primary','en','Kickstart your career in Louisiana Tech’s Construction Engineering Technology program with hands-on training in surveying equipment and the latest construction innovations. You can also earn a certificate in surveying to deepen your expertise. Gain real-world experience estimating and bidding on projects while connecting with industry leaders through student organizations and professional conferences. Participate in groundbreaking research at the Trenchless Technology Center, focusing on underground utilities. In your senior year, collaborate on a large-scale project and present your work to industry sponsors, preparing you for leadership roles in the field. Our graduates excel in diverse sectors; from heavy highway transportation and public works to renewable energy and ready to manage projects that build and sustain communities.','Kickstart your career in Louisiana Tech’s Construction Engineering Technology program with hands-on training in surveying equipment and the latest construction innovations. You can also earn a certificate in surveying to deepen your expertise. Gain real-world experience estimating and bidding on projects while connecting with industry leaders through student organizations and professional conferences. Participate in groundbreaking research at the Trenchless Technology Center, focusing on underground utilities. In your senior year, collaborate on a large-scale project and present your work to industry sponsors, preparing you for leadership roles in the field. Our graduates excel in diverse sectors; from heavy highway transportation and public works to renewable energy and ready to manage projects that build and sustain communities.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.latech.edu/academics/degrees-programs/engineering-science/construction-engineering-technology-bsct.php',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','87bda5d0d36acb78d5d3f5f46459a43058b3aa7556a30bb8e7d6360e82e94852','0a239596dc4aea4a8cac51f104184c7869cd9807cca3b4f28a86e877a0976df1',1,1,1,1 FROM sources WHERE root_url='https://www.latech.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
