INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B40F497F707453423D95','public_higher_education_research',NULL,'Magic in Materials: Caleb Charland’s Photographs of Science | Massachusetts College of Art and Design (MassArt)','https://massart.edu/news/2022/08/magic-materials-caleb-charlande28099s-photographs-science/',NULL,'Massachusetts College of Art and Design','ma-superadmin','United States','North America','public_graduate_higher_education_research_source','2022-10-03T20:18:00+00:00',NULL,'2026-10-05T19:39:12.694Z','institutional_primary','en','&#8220;Growing up in rural Maine, Charland developed a sense of curiosity for natural phenomena. The experimental nature of his work often yields unexpected results measurable only through photographic processes. Charland earned a BFA in photography from MassArt in 2004, an MFA from the School of the Art Institute of Chicago, as a Trustees Fellow, in 2010, and was a participant at the Skowhegan School of Painting and Sculpture in 2009. In 2016 Charland received the prestigious Pollock-Krasner Foundation grant in photography.&#8221;','&#8220;Growing up in rural Maine, Charland developed a sense of curiosity for natural phenomena. The experimental nature of his work often yields unexpected results measurable only through photographic processes. Charland earned a BFA in photography from MassArt in 2004, an MFA from the School of the Art Institute of Chicago, 