INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-46573337CA1D8683270D','public_higher_education_research',NULL,'Quantifying Strength Degradations Resulting from Cyclic Loading in Fine-Grained Soils using Machine Learning','https://www.ndsu.edu/education/research-programs/research-experience-for-teachers-civil-engineering-instruction-for-secondary-education-teachers/background/current-faculty-led-projects/2022-projects/quantifying-strength-degradations-resulting-from-cyclic-loading-in-fine-grai',NULL,'North Dakota State University-Main Campus',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-05T19:43:10.818Z','institutional_primary','en','Cyclic mobility is the loss of shear strength in a soil subjected to cyclic loading, such as from earthquakes, storm waves, or explosions. It plays a critical role in the stability of infrastructure. Unlike other cyclically induced hazards, cyclic mobility is a lesser understood area of geotechnical engineering. Despite substantial efforts on examining the influence of several parameters such as index properties on the shear strength, there is a lack of consensus on expected strength reductions for different loading and environmental conditions. The proposed project aims to establish a data-enabled framework to predict complex dynamic and mechanical behaviors of fine-grained soils under cyclic loading. To research the goal, systematic experiments and machine learning will be integrated to uncover the relationship between the characteristics of clay-silt mixtures and degradation of shear ','Cyclic mobility is the loss of shear strength in a soil subjected to cyclic loading, such as from earthquakes, storm waves, or explosions. It plays a critical role in the stability of infrastructure. Unlike other cyclically induced hazards, cyclic mobility is a lesser understood area of geotechnical engineering. Despite substantial efforts on examining the influence of several parameters such as index properties on the shear strength, there is a lack of consensus on expected strength reductions for different loading and environmental conditions. The proposed project aims to establish a data-enabled framework to predict complex dynamic and mechanical behaviors of fine-grained soils under cyclic loading. To research the goal, systematic experiments and machine learning will be integrated to uncover the relationship between the characteristics of clay-silt mixtures and degradation of shear ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ndsu.edu/education/research-programs/research-experience-for-teachers-civil-engineering-instruction-for-secondary-education-teachers/background/current-faculty-led-projects/2022-projects/quantifying-strength-degradations-resulting-from-cyclic-loading-in-fine-grai',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','71ec5c83b69ea6f7837059e297e2a650856616b4c9238eb31fae0fcfe95a7975','46573337ca1d8683270d85b8aa9d2bc9b66d041aac9738803002c9b8ac953b5a',1,1,1,1 FROM sources WHERE root_url='https://www.ndsu.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO document_search(document_id,search_text,updated_at) SELECT id,'quantifying strength degradations resulting from cyclic loading in fine-grained soils using machine learning cyclic mobility is the loss of shear strength in a soil subjected to cyclic loading such as from earthquakes storm waves or explosions. it plays a critical role in the stability of infrastructure. unlike other cyclically induced hazards cyclic mobility is a lesser understood area of geotechnical engineering. despite substantial efforts on examining the influence of several parameters such as index properties on the shear strength there is a lack of consensus on expected strength reductions for different loading and environmental conditions. the proposed project aims to establish a data-enabled framework to predict complex dynamic and mechanical behaviors of fine-grained soils under cyclic loading. to research the goal systematic experiments and machine learning will be integrated to uncover the relationship between the characteristics of clay-silt mixtures and degradation of shear public higher education research',CURRENT_TIMESTAMP FROM documents WHERE canonical_hash='46573337ca1d8683270d85b8aa9d2bc9b66d041aac9738803002c9b8ac953b5a' ON CONFLICT(document_id) DO UPDATE SET search_text=excluded.search_text,updated_at=CURRENT_TIMESTAMP;
