INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-3D3E0B31CEE27807CAEB','public_higher_education_research',NULL,'Safety Data Sheets (SDS) and Web-based Chemical Inventory Program | Worcester State University','https://www.worcester.edu/about/emergency-management-and-institutional-security/environment-health-safety/safety-data-sheets-sds-and-web-based-chemical-inventory-program/',NULL,'Worcester State University',NULL,'United States','North America','public_graduate_higher_education_research_source',NULL,NULL,'2026-10-05T19:48:55.947Z','institutional_primary','en','Under the Hazard Communication Standard (OSHA requirement 29CFR.1910.120), employers must maintain complete and accurate Safety Data Sheets (SDSs) for all hazardous chemicals. A Safety Data Sheet (SDS) is a detailed document prepared by the manufacturer of a chemical that describes the physical and chemical properties, physical and health hazards, routes of exposure, precautions for safe handling and use, emergency and first-aid procedures, and control measures. To ensure chemical safety in the workplace, SDSs must be available to all employees who may be exposed to hazardous substances while at work. Members of the University community may also use the web based SDS search program to research chemicals used on campus. This chemical inventory program, UNHCEMS, has over 46,50000 entries.','Under the Hazard Communication Standard (OSHA requirement 29CFR.1910.120), employers must maintain complete and accurate Safety Data Sheets (SDSs) for all hazardous chemicals. A Safety Data Sheet (SDS) is a detailed document prepared by the manufacturer of a chemical that describes the physical and chemical properties, physical and health hazards, routes of exposure, precautions for safe handling and use, emergency and first-aid procedures, and control measures. To ensure chemical safety in the workplace, SDSs must be available to all employees who may be exposed to hazardous substances while at work. Members of the University community may also use the web based SDS search program to research chemicals used on campus. This chemical inventory program, UNHCEMS, has over 46,50000 entries.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.worcester.edu/about/emergency-management-and-institutional-security/environment-health-safety/safety-data-sheets-sds-and-web-based-chemical-inventory-program/',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','248d83de366911e5c7f6462e02e232606cdf80e03420e3bf446128931562644a','3d3e0b31cee27807caeb6eaeedff505b01881ebed9a60b23abe7a2b8fb98d30b',1,1,1,1 FROM sources WHERE root_url='https://www.worcester.edu/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
