INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-84A72BEF9260DB9F8665','higher_education_research',NULL,'Project 7: Optimising energy consumption and indoor environmental parameters for occupants’ dynamic usage of buildings using IoT and Digital Twin technologies','https://www.westernsydney.edu.au/centre-for-smart-modern-construction/research/project-7-optimising-energy-consumption-and-indoor-environmental-parameters-for-occupants-dynamic-usage-of-buildings-using-iot-and-digital-twin-technologies',NULL,'Western Sydney University',NULL,'Australia','Oceania','research_block_grant_eligible_higher_education_provider',NULL,NULL,'2026-10-05T19:28:09.642Z','institutional_primary','en','De-Graft Joe Opoku Chair Supervisor Co-Supervisor Co-Supervisor Prof. Srinath Perera Dr Robert Osei-Kyei Dr Whitney Bevan Most studies on buildings’ energy consumption optimisation have considered the building as a static object neglecting its constant interactions with occupants’ behaviour. However, the interactions between buildings and occupants’ behaviour present the structure as a dynamic object. Therefore, identifying the building as a static object cannot provide the real and optimum solution to reduce buildings’ energy consumption. For this reason, most studies have experienced gaps between the predicted and actual energy consumptions in buildings.','De-Graft Joe Opoku Chair Supervisor Co-Supervisor Co-Supervisor Prof. Srinath Perera Dr Robert Osei-Kyei Dr Whitney Bevan Most studies on buildings’ energy consumption optimisation have considered the building as a static object neglecting its constant interactions with occupants’ behaviour. However, the interactions between buildings and occupants’ behaviour present the structure as a dynamic object. Therefore, identifying the building as a static object cannot provide the real and optimum solution to reduce buildings’ energy consumption. For this reason, most studies have experienced gaps between the predicted and actual energy consumptions in buildings.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.westernsydney.edu.au/centre-for-smart-modern-construction/research/project-7-optimising-energy-consumption-and-indoor-environmental-parameters-for-occupants-dynamic-usage-of-buildings-using-iot-and-digital-twin-technologies',NULL,5,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','227f6453524333e62e6a26044c4fa9ba7618e4bd461719cb248cb3cd63630ae8','84a72bef9260db9f8665aaebd02e689599b83acac3803636667d5da7fb7b2931',1,1,1,1 FROM sources WHERE root_url='https://www.westernsydney.edu.au/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
